  // --- Module: core/registry.js ---
const FAMILY_MAP = new Map();
const PRESET_MAP = new Map();
const CATEGORY_MAP = new Map(BUILDING_CATEGORIES.map((c) => [c.id, c]));

function validId(list, value, fallback) {
  return list.some((item) => item.id === value) ? value : fallback;
}

function registerSpecialtyFamily(familyDef) {
  if (!familyDef || !familyDef.id) {
    throw new Error('Specialty building family requires an id');
  }
  const normalized = {
    categoryId: 'commercial_services',
    categories: [],
    label: familyDef.id,
    description: '',
    environmentTags: [],
    supportedLotTypes: ['standalone_commercial', 'compact_urban', 'corner_commercial', 'none'],
    defaultObjectGroups: ['site_amenities', 'waste_utility', 'rooftop_mep', 'signage_lighting'],
    featureSchema: [],
    presets: [],
    defaults: {},
    buildStructure: null,
    planObjects: null,
    ...familyDef
  };
  normalized.categories = Array.from(new Set([normalized.categoryId, ...(normalized.categories || [])].filter(Boolean)));
  normalized.presets = (normalized.presets || []).map((preset) => ({
    ...preset,
    familyId: normalized.id,
    categoryId: normalized.categoryId,
    environmentTags: Array.from(new Set([...(normalized.environmentTags || []), ...(preset.environmentTags || [])])),
    params: { ...(normalized.defaults || {}), ...(preset.params || {}) }
  }));

  normalized._searchText = [
    normalized.id,
    normalized.label,
    normalized.description,
    normalized.categoryId,
    ...(normalized.environmentTags || []),
    ...normalized.presets.flatMap((p) => [p.id, p.label, p.description || '', ...(p.environmentTags || [])])
  ].join(' ').toLowerCase();

  FAMILY_MAP.set(normalized.id, normalized);
  for (const preset of normalized.presets) {
    PRESET_MAP.set(preset.id, preset);
  }
  return normalized;
}

function getSpecialtyFamily(familyId) {
  return FAMILY_MAP.get(familyId) || null;
}

function getAllSpecialtyFamilies() {
  return Array.from(FAMILY_MAP.values());
}

function getSpecialtyPreset(presetId) {
  return PRESET_MAP.get(presetId) || null;
}

function getAllSpecialtyPresets() {
  return Array.from(PRESET_MAP.values());
}

function getPresetsForSpecialtyFamily(familyId) {
  const fam = getSpecialtyFamily(familyId);
  return fam ? fam.presets : [];
}

function getSpecialtyCategoryMeta(categoryId) {
  return CATEGORY_MAP.get(categoryId) || BUILDING_CATEGORIES[0];
}

function searchSpecialtyCatalog(query = '', filters = {}) {
  const q = String(query || '').trim().toLowerCase();
  const cat = filters.categoryId && filters.categoryId !== 'all' ? filters.categoryId : null;
  const tag = filters.environmentTag && filters.environmentTag !== 'all' ? filters.environmentTag.toLowerCase() : null;
  const era = filters.architecturalEra && filters.architecturalEra !== 'all' ? filters.architecturalEra : null;

  return getAllSpecialtyFamilies().filter((fam) => {
    if (cat && !fam.categories.includes(cat)) return false;
    if (tag) {
      const hasTag = fam.environmentTags.some((t) => t.toLowerCase() === tag)
        || fam.presets.some((p) => p.environmentTags.some((t) => t.toLowerCase() === tag));
      if (!hasTag) return false;
    }
    if (era) {
      const hasEra = fam.presets.some((p) => p.params?.architecturalEra === era);
      if (!hasEra) return false;
    }
    if (q && !fam._searchText.includes(q)) return false;
    return true;
  });
}

function getSchemaForFamily(familyId) {
  const fam = getSpecialtyFamily(familyId);
  const familyFields = (fam?.featureSchema || []).map((f) => ({
    ...f,
    tab: f.tab || 'features',
    isFamilySpecific: true
  }));
  return [...SHARED_SCHEMA_FIELDS, ...familyFields];
}

function buildDefaultSpecialtyConfig(familyId = 'gas_station', presetId = null) {
  const fam = getSpecialtyFamily(familyId) || getAllSpecialtyFamilies()[0] || null;
  const preset = (presetId && getSpecialtyPreset(presetId)) || (fam && fam.presets[0]) || null;
  const base = copy(BASE_BUILDING_CONFIG);
  if (fam) {
    base.familyId = fam.id;
    Object.assign(base, copy(fam.defaults || {}));
  }
  if (preset) {
    base.familyId = preset.familyId;
    base.presetId = preset.id;
    Object.assign(base, copy(preset.params || {}));
  }
  return sanitiseSpecialtyConfig(base);
}

function sanitiseSpecialtyConfig(rawCfg = {}) {
  const fam = getSpecialtyFamily(rawCfg.familyId) || getAllSpecialtyFamilies()[0] || null;
  const preset = (rawCfg.presetId && getSpecialtyPreset(rawCfg.presetId)) || (fam && fam.presets[0]) || null;

  const merged = {
    ...copy(BASE_BUILDING_CONFIG),
    ...(fam ? copy(fam.defaults || {}) : {}),
    ...(preset && preset.familyId === fam?.id ? copy(preset.params || {}) : {}),
    ...copy(rawCfg || {})
  };

  if (fam) merged.familyId = fam.id;
  if (preset && preset.familyId === fam?.id) merged.presetId = preset.id;
  else if (fam && fam.presets[0]) merged.presetId = fam.presets[0].id;

  merged.seed = clamp(Math.round(Number(merged.seed) || 2026), 1, 99999999);
  merged.width = clamp(merged.width, 3.5, 64);
  merged.depth = clamp(merged.depth, 3.0, 52);
  merged.floors = clamp(Math.round(Number(merged.floors) || 1), 1, 12);
  merged.floorHeight = clamp(merged.floorHeight, 2.6, 7.5);
  merged.roofPitchHeight = clamp(merged.roofPitchHeight, 0.4, 4.5);
  merged.parapetHeight = clamp(merged.parapetHeight, 0.1, 1.5);
  merged.windowDensity = clamp(merged.windowDensity, 0, 1);
  merged.entranceCount = clamp(Math.round(Number(merged.entranceCount) || 1), 1, 3);
  merged.outdoorObjectDensity = clamp(merged.outdoorObjectDensity, 0, 1);

  merged.architecturalEra = validId(ARCHITECTURAL_ERAS, merged.architecturalEra, 'contemporary');
  merged.exteriorMaterial = validId(MATERIAL_FAMILIES, merged.exteriorMaterial, 'mixed_commercial');
  merged.condition = validId(CONDITION_LEVELS, merged.condition, 'clean');
  merged.lotType = validId(LOT_TYPES, merged.lotType, 'standalone_commercial');
  merged.roofStyle = validId(ROOF_STYLES, merged.roofStyle, 'flat');
  merged.windowStyle = validId(WINDOW_STYLES, merged.windowStyle, 'storefront');
  merged.entranceLocation = validId(ENTRANCE_LOCATIONS, merged.entranceLocation, 'front_center');
  merged.signageStyle = validId(SIGNAGE_STYLES, merged.signageStyle, 'illuminated_fascia');
  merged.parkingConfig = validId(PARKING_CONFIGS, merged.parkingConfig, 'front_row');
  merged.sidewalkConfig = validId(SIDEWALK_CONFIGS, merged.sidewalkConfig, 'front_only');

  merged.lotWidth = clamp(Math.max(merged.lotWidth, merged.width + 2), 8, 96);
  merged.lotDepth = clamp(Math.max(merged.lotDepth, merged.depth + 2), 8, 88);
  merged.frontSetback = clamp(merged.frontSetback, 1.5, 24);
  merged.sideSetback = clamp(merged.sideSetback, 1.0, 18);
  merged.parkingCount = clamp(Math.round(Number(merged.parkingCount) || 0), 0, 28);

  merged.primaryColor = colorHex(merged.primaryColor, '#d9dfe6');
  merged.secondaryColor = colorHex(merged.secondaryColor, '#2c4a6e');
  merged.accentColor = colorHex(merged.accentColor, '#d93c2b');
  merged.trimColor = colorHex(merged.trimColor, '#36414c');
  merged.glassColor = colorHex(merged.glassColor, '#4e83a6');

  merged.signText = String(merged.signText || fam?.label || 'Specialty Building').slice(0, 36);
  merged.includeBuildingLayer = merged.includeBuildingLayer !== false;
  merged.includeLot = merged.includeLot !== false && merged.lotType !== 'none';
  merged.includeObjectsLayer = merged.includeObjectsLayer !== false;
  merged.disabledObjectGroups = Array.isArray(merged.disabledObjectGroups) ? merged.disabledObjectGroups : [];

  // Clamp family-specific schema bounds
  if (fam && Array.isArray(fam.featureSchema)) {
    for (const field of fam.featureSchema) {
      if (!field.key) continue;
      if (merged[field.key] === undefined && field.default !== undefined) {
        merged[field.key] = field.default;
      }
      if (field.type === 'range' || field.type === 'number') {
        const val = Number(merged[field.key]);
        merged[field.key] = clamp(Number.isFinite(val) ? val : (field.default ?? field.min ?? 0), field.min ?? -999, field.max ?? 999);
        if (field.step && field.step >= 1) merged[field.key] = Math.round(merged[field.key]);
      } else if (field.type === 'boolean') {
        merged[field.key] = Boolean(merged[field.key]);
      } else if (field.type === 'select' && Array.isArray(field.options)) {
        const optId = (opt) => (Array.isArray(opt) ? opt[0] : opt?.id);
        const valid = field.options.some((opt) => optId(opt) === merged[field.key]);
        if (!valid) merged[field.key] = field.default ?? optId(field.options[0]);
      }
    }
  }

  return merged;
}

function applySpecialtyPresetWithLocks(currentCfg, presetId, locks = new Set()) {
  const preset = getSpecialtyPreset(presetId);
  if (!preset) return sanitiseSpecialtyConfig(currentCfg);
  const next = buildDefaultSpecialtyConfig(preset.familyId, preset.id);
  next.seed = currentCfg?.seed || next.seed;
  next.variationStrength = currentCfg?.variationStrength || next.variationStrength;
  next.lightingTime = currentCfg?.lightingTime || next.lightingTime;

  const sameFamily = currentCfg && currentCfg.familyId === preset.familyId;
  for (const key of locks) {
    if (currentCfg && currentCfg[key] !== undefined) {
      if (sameFamily || ['seed', 'variationStrength', 'lightingTime', 'primaryColor', 'secondaryColor', 'accentColor', 'trimColor', 'glassColor', 'condition', 'architecturalEra'].includes(key)) {
        next[key] = copy(currentCfg[key]);
      }
    }
  }
  return sanitiseSpecialtyConfig(next);
}

  // --- Module: core/seeded-generation.js ---
function createBuildingRngStreams(seed = 2026) {
  const base = (Number(seed) || 2026) >>> 0;
  return {
    base,
    structure: forkRng(base, 'structure'),
    lot: forkRng(base, 'lot'),
    materials: forkRng(base, 'materials'),
    objects: forkRng(base, 'objects'),
    decoration: forkRng(base, 'decoration')
  };
}

function getVariationFactor(strengthId = 'subtle') {
  const found = VARIATION_STRENGTHS.find((v) => v.id === strengthId);
  return found ? found.factor : 0.28;
}

function applySeedVariation(rawCfg, locks = new Set()) {
  const cfg = sanitiseSpecialtyConfig(rawCfg);
  const factor = getVariationFactor(cfg.variationStrength);
  if (factor <= 0.001) return cfg;

  const streams = createBuildingRngStreams(cfg.seed);
  const out = copy(cfg);
  const fam = getSpecialtyFamily(cfg.familyId);
  const minW = fam?.minWidth || 4.0;
  const maxW = fam?.maxWidth || 62.0;
  const minD = fam?.minDepth || 3.5;
  const maxD = fam?.maxDepth || 50.0;

  if (!locks.has('width')) {
    out.width = roundNum(clamp(cfg.width * (1 + (streams.structure() - 0.5) * 0.22 * factor), minW, maxW), 1);
  }
  if (!locks.has('depth')) {
    out.depth = roundNum(clamp(cfg.depth * (1 + (streams.structure() - 0.5) * 0.22 * factor), minD, maxD), 1);
  }
  if (!locks.has('floorHeight')) {
    out.floorHeight = roundNum(clamp(cfg.floorHeight + (streams.structure() - 0.5) * 0.45 * factor, 2.7, 7.2), 1);
  }
  if (!locks.has('windowDensity')) {
    out.windowDensity = roundNum(clamp(cfg.windowDensity + (streams.structure() - 0.5) * 0.28 * factor, 0.15, 0.98), 2);
  }
  if (!locks.has('parapetHeight')) {
    out.parapetHeight = roundNum(clamp(cfg.parapetHeight + (streams.structure() - 0.5) * 0.25 * factor, 0.12, 1.3), 2);
  }
  if (!locks.has('frontSetback') && cfg.includeLot) {
    out.frontSetback = roundNum(clamp(cfg.frontSetback + (streams.lot() - 0.5) * 2.2 * factor, 2.0, 22), 1);
  }
  if (!locks.has('parkingCount') && cfg.includeLot && cfg.parkingCount > 0) {
    out.parkingCount = clamp(cfg.parkingCount + Math.round((streams.lot() - 0.5) * 4 * factor), 1, 26);
  }
  if (!locks.has('primaryColor') && factor >= 0.45) {
    const tintTarget = streams.materials() > 0.5 ? '#e4e8ec' : '#3a4654';
    out.primaryColor = mixHex(cfg.primaryColor, tintTarget, 0.12 * factor);
  }
  if (!locks.has('secondaryColor') && factor >= 0.45) {
    const tintTarget = streams.materials() > 0.5 ? '#26466d' : '#7a3b2e';
    out.secondaryColor = mixHex(cfg.secondaryColor, tintTarget, 0.14 * factor);
  }
  if (!locks.has('outdoorObjectDensity')) {
    out.outdoorObjectDensity = roundNum(clamp(cfg.outdoorObjectDensity + (streams.objects() - 0.5) * 0.25 * factor, 0.25, 1.0), 2);
  }

  return sanitiseSpecialtyConfig(out);
}

function randomizeSettings(rawCfg, scope = 'all', locks = new Set()) {
  const cfg = sanitiseSpecialtyConfig(rawCfg);
  const next = copy(cfg);
  const r = forkRng((cfg.seed || 2026) + Math.floor(Math.random() * 99999), scope);
  const schema = getSchemaForFamily(cfg.familyId);

  for (const field of schema) {
    if (!field.key || locks.has(field.key)) continue;
    if (field.key === 'seed' || field.key === 'exportScope' || field.key === 'lightingTime') continue;
    if (scope !== 'all' && field.tab !== scope) continue;

    if (field.type === 'range' || field.type === 'number') {
      const step = field.step || 0.1;
      const raw = randBetween(r, field.min ?? 0, field.max ?? 1);
      next[field.key] = roundNum(Math.round(raw / step) * step, 2);
    } else if (field.type === 'select' && Array.isArray(field.options) && field.options.length > 0) {
      const getOptId = (opt) => (Array.isArray(opt) ? opt[0] : opt?.id);
      if (field.key === 'lotType' && cfg.includeLot) {
        const nonEmpty = field.options.filter((opt) => getOptId(opt) !== 'none');
        next[field.key] = getOptId(pick(r, nonEmpty));
      } else {
        next[field.key] = getOptId(pick(r, field.options));
      }
    } else if (field.type === 'boolean') {
      if (field.key === 'includeBuildingLayer' || field.key === 'includeLot' || field.key === 'includeObjectsLayer') continue;
      next[field.key] = r() > 0.35;
    } else if (field.type === 'color') {
      const palette = ['#8d4c3b', '#c9d4dc', '#3b5875', '#d9a441', '#456b52', '#525a64', '#b84035', '#dfd7c8'];
      next[field.key] = pick(r, palette);
    }
  }

  if (scope === 'all' && !locks.has('exteriorMaterial')) {
    next.exteriorMaterial = pick(r, MATERIAL_FAMILIES).id;
  }

  return sanitiseSpecialtyConfig(next);
}

  // --- Module: core/placement-anchors.js ---
const ANCHOR_CATEGORIES = [
  'storefront',
  'window_display',
  'entrance',
  'sidewalk',
  'parking',
  'service_yard',
  'roof',
  'wall',
  'loading_dock',
  'patio',
  'drive_thru',
  'fuel_island',
  'equipment_frontage',
  'interior_display',
  'roadside'
];

function createPlacementContext(cfg) {
  return {
    anchors: new Map(),
    buildingFootprints: [],
    entranceClearances: [],
    laneClearances: [],
    roofBounds: [],
    placedBoxes: [],
    diagnostics: {
      placedCount: 0,
      nudgedCount: 0,
      rejectedCollisions: [],
      missingDependencies: []
    },
    cfg
  };
}

function registerAnchor(ctx, anchorDef) {
  if (!ctx || !anchorDef || !anchorDef.id) return null;
  const anchor = {
    id: anchorDef.id,
    category: anchorDef.category || 'storefront',
    position: [
      roundNum(anchorDef.position?.[0] || 0, 4),
      roundNum(anchorDef.position?.[1] || 0, 4),
      roundNum(anchorDef.position?.[2] || 0, 4)
    ],
    rotationY: roundNum(anchorDef.rotationY || 0, 4),
    normal: anchorDef.normal || [0, 0, 1],
    surfaceY: roundNum(anchorDef.surfaceY ?? anchorDef.position?.[1] ?? 0, 4),
    span: anchorDef.span || null,
    bounds: anchorDef.bounds || null
  };
  ctx.anchors.set(anchor.id, anchor);
  return anchor;
}

function registerBuildingFootprint(ctx, boxDef) {
  if (!ctx || !boxDef) return;
  ctx.buildingFootprints.push({
    id: boxDef.id || `bldg_${ctx.buildingFootprints.length}`,
    minX: roundNum(boxDef.minX, 4),
    maxX: roundNum(boxDef.maxX, 4),
    minZ: roundNum(boxDef.minZ, 4),
    maxZ: roundNum(boxDef.maxZ, 4),
    maxY: roundNum(boxDef.maxY || 4, 4)
  });
}

function registerEntranceClearance(ctx, entranceDef) {
  if (!ctx || !entranceDef) return;
  const pos = entranceDef.position || { x: 0, y: 0, z: 0 };
  const n = entranceDef.normal || { x: 0, y: 0, z: 1 };
  const clearW = entranceDef.clearanceWidth || (entranceDef.role === 'garage' || entranceDef.role === 'loading' ? 3.8 : 2.1);
  const clearD = entranceDef.clearanceDepth || (entranceDef.role === 'garage' || entranceDef.role === 'loading' ? 4.5 : 2.2);
  const cx = pos.x + n.x * (clearD * 0.5 + 0.15);
  const cz = pos.z + n.z * (clearD * 0.5 + 0.15);
  const absX = Math.abs(n.x) > 0.5;
  const hx = (absX ? clearD : clearW) * 0.5;
  const hz = (absX ? clearW : clearD) * 0.5;
  ctx.entranceClearances.push({
    id: entranceDef.id,
    role: entranceDef.role,
    minX: roundNum(cx - hx, 4),
    maxX: roundNum(cx + hx, 4),
    minZ: roundNum(cz - hz, 4),
    maxZ: roundNum(cz + hz, 4),
    minY: roundNum(pos.y || 0, 4),
    maxY: roundNum((pos.y || 0) + 2.8, 4)
  });
}

function registerLaneClearance(ctx, laneBox) {
  if (!ctx || !laneBox) return;
  ctx.laneClearances.push({
    id: laneBox.id || `lane_${ctx.laneClearances.length}`,
    kind: laneBox.kind || 'driveway',
    minX: roundNum(laneBox.minX, 4),
    maxX: roundNum(laneBox.maxX, 4),
    minZ: roundNum(laneBox.minZ, 4),
    maxZ: roundNum(laneBox.maxZ, 4)
  });
}

function registerRoofBound(ctx, roofBox) {
  if (!ctx || !roofBox) return;
  ctx.roofBounds.push({
    id: roofBox.id || `roof_${ctx.roofBounds.length}`,
    minX: roundNum(roofBox.minX, 4),
    maxX: roundNum(roofBox.maxX, 4),
    minZ: roundNum(roofBox.minZ, 4),
    maxZ: roundNum(roofBox.maxZ, 4),
    y: roundNum(roofBox.y, 4)
  });
}

function boxesOverlap2D(a, b, pad = 0.04) {
  return (
    a.minX < b.maxX - pad &&
    a.maxX > b.minX + pad &&
    a.minZ < b.maxZ - pad &&
    a.maxZ > b.minZ + pad
  );
}

function boxesOverlap3D(a, b, pad = 0.04) {
  if (!boxesOverlap2D(a, b, pad)) return false;
  return a.minY < b.maxY - pad && a.maxY > b.minY + pad;
}

function resolveSpecWorldPose(ctx, spec) {
  const anchor = spec.anchorId ? ctx.anchors.get(spec.anchorId) : null;
  const localPos = spec.localOffset || spec.position || [0, 0, 0];
  const baseRot = anchor ? anchor.rotationY : 0;
  const rotY = baseRot + (spec.rotationY || 0);

  let wx = localPos[0] || 0;
  let wy = localPos[1] || 0;
  let wz = localPos[2] || 0;

  if (anchor) {
    const c = Math.cos(baseRot);
    const s = Math.sin(baseRot);
    const rx = wx * c + wz * s;
    const rz = -wx * s + wz * c;
    wx = anchor.position[0] + rx;
    wy = anchor.surfaceY + (localPos[1] || 0);
    wz = anchor.position[2] + rz;
  }

  return {
    anchor,
    x: roundNum(wx, 4),
    y: roundNum(wy, 4),
    z: roundNum(wz, 4),
    rotationY: roundNum(rotY, 4)
  };
}

function validateAndReservePlacement(ctx, spec, halfExtents) {
  const pose = resolveSpecWorldPose(ctx, spec);
  const hx = Math.max(0.12, (halfExtents?.x || 0.35) * (spec.scale || 1));
  const hy = Math.max(0.12, (halfExtents?.y || 0.45) * (spec.scale || 1));
  const hz = Math.max(0.12, (halfExtents?.z || 0.35) * (spec.scale || 1));

  // Rotated AABB extent in XZ
  const absCos = Math.abs(Math.cos(pose.rotationY));
  const absSin = Math.abs(Math.sin(pose.rotationY));
  const ex = hx * absCos + hz * absSin;
  const ez = hx * absSin + hz * absCos;

  let x = pose.x;
  let y = pose.y;
  let z = pose.z;
  let nudged = false;

  const isRoof = pose.anchor?.category === 'roof' || spec.placementLayer === 'roof';
  const isWall = pose.anchor?.category === 'wall' || spec.placementLayer === 'wall';
  const isInterior = pose.anchor?.category === 'interior_display' || spec.placementLayer === 'interior';

  // Ensure grounded on surface unless wall/roof/interior
  if (!isRoof && !isWall && !isInterior && !spec.allowElevated) {
    y = Math.max(0, pose.anchor ? pose.anchor.surfaceY : 0);
  }

  // Clamp inside roof bounds if rooftop prop
  if (isRoof && ctx.roofBounds.length > 0 && !spec.skipRoofClamp) {
    const rb = ctx.roofBounds[0];
    const margin = 0.25;
    const clampedX = clamp(x, rb.minX + ex + margin, rb.maxX - ex - margin);
    const clampedZ = clamp(z, rb.minZ + ez + margin, rb.maxZ - ez - margin);
    if (Math.abs(clampedX - x) > 0.01 || Math.abs(clampedZ - z) > 0.01) {
      x = clampedX;
      z = clampedZ;
      nudged = true;
    }
    y = rb.y;
  }

  const makeBox = (cx, cy, cz) => ({
    minX: cx - ex,
    maxX: cx + ex,
    minY: cy,
    maxY: cy + hy * 2,
    minZ: cz - ez,
    maxZ: cz + ez
  });

  let candBox = makeBox(x, y, z);

  // Check entrance clearances for ground exterior objects
  if (!isRoof && !isWall && !isInterior && !spec.allowInEntrance) {
    for (const ent of ctx.entranceClearances) {
      if (boxesOverlap2D(candBox, ent, 0.02)) {
        // Attempt lateral nudge outside entrance clearance
        const dxLeft = ent.minX - ex - 0.12;
        const dxRight = ent.maxX + ex + 0.12;
        const altX = Math.abs(x - dxLeft) < Math.abs(x - dxRight) ? dxLeft : dxRight;
        const testBox = makeBox(altX, y, z);
        if (!ctx.buildingFootprints.some((b) => boxesOverlap2D(testBox, b, 0.02))) {
          x = altX;
          candBox = testBox;
          nudged = true;
        } else {
          ctx.diagnostics.rejectedCollisions.push({
            familyId: spec.familyId,
            presetId: spec.presetId,
            reason: `Blocked entrance ${ent.id}`
          });
          return { accepted: false, reason: 'blocked_entrance' };
        }
      }
    }
  }

  // Check building wall intrusion for exterior ground objects
  if (!isRoof && !isWall && !isInterior && !spec.allowInsideBuilding) {
    for (const bldg of ctx.buildingFootprints) {
      if (boxesOverlap2D(candBox, bldg, 0.03)) {
        // Push outward along nearest axis
        const pushFront = bldg.maxZ + ez + 0.08;
        const pushBack = bldg.minZ - ez - 0.08;
        const pushLeft = bldg.minX - ex - 0.08;
        const pushRight = bldg.maxX + ex + 0.08;
        const candidates = [
          { x, z: pushFront, dist: Math.abs(z - pushFront) },
          { x, z: pushBack, dist: Math.abs(z - pushBack) },
          { x: pushLeft, z, dist: Math.abs(x - pushLeft) },
          { x: pushRight, z, dist: Math.abs(x - pushRight) }
        ].sort((a, b) => a.dist - b.dist);
        x = candidates[0].x;
        z = candidates[0].z;
        candBox = makeBox(x, y, z);
        nudged = true;
      }
    }
  }

  // Check vehicle lane clearance for ground props
  if (!isRoof && !isWall && !isInterior && !spec.allowInLane) {
    for (const lane of ctx.laneClearances) {
      if (boxesOverlap2D(candBox, lane, 0.04)) {
        ctx.diagnostics.rejectedCollisions.push({
          familyId: spec.familyId,
          presetId: spec.presetId,
          reason: `Blocked vehicle lane ${lane.id}`
        });
        return { accepted: false, reason: 'blocked_lane' };
      }
    }
  }

  // Check overlap against already placed props
  if (!spec.allowOverlap) {
    for (const prev of ctx.placedBoxes) {
      if (boxesOverlap3D(candBox, prev, 0.05)) {
        // Try a small lateral shift before rejecting
        let resolved = false;
        for (const offset of [ex * 2.1 + 0.15, -(ex * 2.1 + 0.15), ez * 2.1 + 0.15, -(ez * 2.1 + 0.15)]) {
          const tx = Math.abs(offset) === ex * 2.1 + 0.15 ? x + offset : x;
          const tz = Math.abs(offset) === ez * 2.1 + 0.15 ? z + offset : z;
          const testBox = makeBox(tx, y, tz);
          const hitsPrev = ctx.placedBoxes.some((p) => boxesOverlap3D(testBox, p, 0.05));
          const hitsBldg = !isRoof && !isWall && !isInterior && !spec.allowInsideBuilding &&
            ctx.buildingFootprints.some((b) => boxesOverlap2D(testBox, b, 0.03));
          const hitsEnt = !isRoof && !isWall && !isInterior && !spec.allowInEntrance &&
            ctx.entranceClearances.some((e) => boxesOverlap2D(testBox, e, 0.02));
          if (!hitsPrev && !hitsBldg && !hitsEnt) {
            x = tx;
            z = tz;
            candBox = testBox;
            nudged = true;
            resolved = true;
            break;
          }
        }
        if (!resolved) {
          ctx.diagnostics.rejectedCollisions.push({
            familyId: spec.familyId,
            presetId: spec.presetId,
            reason: `Overlapped existing prop ${prev.familyId}`
          });
          return { accepted: false, reason: 'prop_overlap' };
        }
      }
    }
  }

  ctx.placedBoxes.push({
    ...candBox,
    familyId: spec.familyId,
    presetId: spec.presetId
  });
  ctx.diagnostics.placedCount += 1;
  if (nudged) ctx.diagnostics.nudgedCount += 1;

  return {
    accepted: true,
    nudged,
    position: [roundNum(x, 4), roundNum(y, 4), roundNum(z, 4)],
    rotationY: pose.rotationY,
    bounds: candBox
  };
}

  // --- Module: core/object-integration.js ---
const OBJECT_GROUP_LABELS = {
  fueling: 'Fueling & Pump Island Equipment',
  site_amenities: 'Site & Customer Amenities',
  waste_utility: 'Waste, Dumpsters & Utilities',
  rooftop_mep: 'Rooftop Hvac & Communications',
  seating_patio: 'Patio & Outdoor Seating',
  signage_lighting: 'Roadside Signs & Exterior Lighting',
  service_equipment: 'Garage, Dock & Workshop Equipment',
  interior_display: 'Visible Interior Window Displays'
};

function resolveCityObjectApi(options = {}) {
  if ('cityObjectApi' in options) {
    const provided = options.cityObjectApi;
    if (provided && typeof provided.ensureCityObjectRegistry === 'function') {
      provided.ensureCityObjectRegistry();
    }
    return provided || null;
  }
  if (typeof globalThis !== 'undefined' && globalThis.BCityObjectSuite) {
    if (typeof globalThis.BCityObjectSuite.ensureCityObjectRegistry === 'function') {
      globalThis.BCityObjectSuite.ensureCityObjectRegistry();
    }
    return globalThis.BCityObjectSuite;
  }
  return null;
}

function buildLayerCObjects(objectSpecs, placementCtx, cfg, options = {}) {
  const layerGroup = new THREE.Group();
  layerGroup.name = 'LayerC_EnvironmentalObjects';

  const api = resolveCityObjectApi(options);
  const disabledGroups = new Set(cfg.disabledObjectGroups || []);
  const density = cfg.outdoorObjectDensity !== undefined ? cfg.outdoorObjectDensity : 0.85;

  const placedRecords = [];
  const missingDependencies = [];
  const availableGroups = new Set();

  for (let idx = 0; idx < (objectSpecs || []).length; idx++) {
    const spec = objectSpecs[idx];
    if (!spec || !spec.familyId) continue;
    const groupKey = spec.groupKey || 'site_amenities';
    availableGroups.add(groupKey);

    if (!cfg.includeObjectsLayer) continue;
    if (disabledGroups.has(groupKey)) continue;
    if (spec.minDensity !== undefined && density < spec.minDensity) continue;

    if (!api) {
      missingDependencies.push({
        familyId: spec.familyId,
        presetId: spec.presetId || null,
        groupKey,
        reason: 'City Object Suite API is not loaded'
      });
      continue;
    }

    const hasFam = typeof api.hasObjectFamily === 'function'
      ? api.hasObjectFamily(spec.familyId)
      : Boolean(api.getObjectFamily?.(spec.familyId));

    if (!hasFam) {
      missingDependencies.push({
        familyId: spec.familyId,
        presetId: spec.presetId || null,
        groupKey,
        reason: `Missing City Object family "${spec.familyId}"`
      });
      continue;
    }

    let objCfg;
    try {
      objCfg = api.buildDefaultConfigForFamily(spec.familyId, spec.presetId || null);
    } catch (err) {
      missingDependencies.push({
        familyId: spec.familyId,
        presetId: spec.presetId || null,
        groupKey,
        reason: err?.message || 'Failed to resolve preset config'
      });
      continue;
    }

    objCfg.seed = spec.seed !== undefined ? spec.seed : ((cfg.seed || 2026) + (idx + 1) * 97);
    objCfg.lightingTime = cfg.lightingTime || 'day';
    objCfg.condition = spec.condition || cfg.condition || 'clean';
    objCfg.variationMode = 'subtle';
    if (spec.overrides) {
      Object.assign(objCfg, copy(spec.overrides));
    }
    if (spec.materialOverrides) {
      Object.assign(objCfg, copy(spec.materialOverrides));
    }

    let objGroup;
    try {
      objGroup = api.buildCityObject(objCfg, {
        lightingTime: cfg.lightingTime || 'day',
        applyVariation: spec.applyVariation !== false
      });
    } catch (err) {
      missingDependencies.push({
        familyId: spec.familyId,
        presetId: spec.presetId || null,
        groupKey,
        reason: err?.message || 'Failed to build City Object geometry'
      });
      continue;
    }

    // Measure object bounds for placement validation
    const box = new THREE.Box3().setFromObject(objGroup);
    const size = new THREE.Vector3();
    if (!box.isEmpty()) box.getSize(size);
    const halfExtents = {
      x: Math.max(0.15, size.x * 0.5),
      y: Math.max(0.15, size.y * 0.5),
      z: Math.max(0.15, size.z * 0.5)
    };

    // Align bottom to y=0 in local space for ground_standing / roof_mounted objects
    if (!box.isEmpty() && !spec.preserveLocalOriginY) {
      const bottomOffset = -box.min.y;
      if (Math.abs(bottomOffset) > 0.002 && Math.abs(bottomOffset) < 2.5) {
        for (const child of objGroup.children) {
          child.position.y += bottomOffset;
        }
      }
    }

    const placement = placementCtx
      ? validateAndReservePlacement(placementCtx, spec, halfExtents)
      : (() => {
        const p = resolveSpecWorldPose(placementCtx, spec);
        return { accepted: true, nudged: false, position: [p.x, p.y, p.z], rotationY: p.rotationY };
      })();

    if (!placement.accepted) {
      objGroup.traverse((child) => {
        if (child.geometry) child.geometry.dispose();
      });
      continue;
    }

    const scale = spec.scale || 1;
    objGroup.position.set(placement.position[0], placement.position[1], placement.position[2]);
    objGroup.rotation.y = placement.rotationY;
    if (scale !== 1) objGroup.scale.setScalar(scale);

    objGroup.name = `Prop_${spec.familyId}_${idx}`;
    objGroup.userData = {
      ...(objGroup.userData || {}),
      layer: 'LayerC_EnvironmentalObjects',
      groupKey,
      anchorId: spec.anchorId || null,
      sourceFamilyId: spec.familyId,
      sourcePresetId: objCfg.presetId || spec.presetId || null,
      seed: objCfg.seed
    };

    // Group into named subgroups per groupKey
    let subgroup = layerGroup.getObjectByName(`ObjectGroup_${groupKey}`);
    if (!subgroup) {
      subgroup = new THREE.Group();
      subgroup.name = `ObjectGroup_${groupKey}`;
      layerGroup.add(subgroup);
    }
    subgroup.add(objGroup);

    placedRecords.push({
      id: objGroup.name,
      familyId: spec.familyId,
      presetId: objCfg.presetId || spec.presetId || null,
      groupKey,
      anchorId: spec.anchorId || null,
      seed: objCfg.seed,
      positionMeters: placement.position,
      rotationY: roundNum(placement.rotationY, 4),
      scale,
      nudged: Boolean(placement.nudged),
      dimensionsMeters: {
        width: roundNum(size.x * scale, 3),
        height: roundNum(size.y * scale, 3),
        depth: roundNum(size.z * scale, 3)
      }
    });
  }

  if (placementCtx) {
    placementCtx.diagnostics.missingDependencies = missingDependencies;
  }

  return {
    group: layerGroup,
    placedRecords,
    missingDependencies,
    availableGroups: Array.from(availableGroups)
  };
}

  // --- Module: core/lot-layout.js ---
function computeLotLayout(cfg, buildingBox, placementCtx = null, options = {}) {
  const enabled = Boolean(cfg.includeLot && cfg.lotType !== 'none');
  const bw = buildingBox?.width || cfg.width;
  const bd = buildingBox?.depth || cfg.depth;

  if (!enabled) {
    return {
      enabled: false,
      lotType: 'none',
      bounds: {
        minX: roundNum(-bw * 0.5, 4),
        maxX: roundNum(bw * 0.5, 4),
        minZ: roundNum(-bd * 0.5, 4),
        maxZ: roundNum(bd * 0.5, 4),
        width: roundNum(bw, 4),
        depth: roundNum(bd, 4)
      },
      sidewalks: [],
      driveways: [],
      parkingStalls: [],
      landscapingBeds: [],
      fences: [],
      patio: null,
      serviceYard: null,
      loadingApron: null
    };
  }

  const frontPad = clamp(cfg.frontSetback || 6.0, 1.8, 24.0);
  const sidePad = clamp(cfg.sideSetback || 3.5, 1.2, 18.0);
  const rearPad = clamp(options.rearMargin ?? (cfg.serviceAccess ? 4.8 : 2.8), 1.5, 18.0);

  const lotW = Math.max(cfg.lotWidth || (bw + sidePad * 2), bw + sidePad * 2);
  const lotD = Math.max(cfg.lotDepth || (bd + frontPad + rearPad), bd + frontPad + rearPad);

  const halfW = lotW * 0.5;
  // Center building along X, offset along Z so frontSetback is in +Z
  const bldgCenterZ = -lotD * 0.5 + rearPad + bd * 0.5;
  const lotMinZ = bldgCenterZ - bd * 0.5 - rearPad;
  const lotMaxZ = bldgCenterZ + bd * 0.5 + frontPad;
  const actualLotD = lotMaxZ - lotMinZ;

  // Keep building centered at origin and offset lot around it
  const minX = -halfW;
  const maxX = halfW;
  const minZ = -bd * 0.5 - rearPad;
  const maxZ = bd * 0.5 + frontPad;

  const isCivic = cfg.lotType === 'civic_plaza';
  const isIndustrial = cfg.lotType === 'industrial_service' || cfg.lotType === 'multi_building_facility';
  const isUrban = cfg.lotType === 'compact_urban';
  const surfaceKind = isCivic ? 'plaza_stone' : isUrban ? 'concrete' : 'asphalt';

  // Sidewalks
  const sidewalks = [];
  const swW = isCivic ? 3.2 : 2.4;
  if (cfg.sidewalkConfig !== 'none') {
    sidewalks.push({
      id: 'sw_front',
      x: 0,
      z: maxZ - swW * 0.5,
      width: lotW,
      depth: swW,
      y: 0.08
    });
    if (cfg.cornerLot || cfg.sidewalkConfig === 'corner_wrap' || cfg.sidewalkConfig === 'full_perimeter') {
      sidewalks.push({
        id: 'sw_right',
        x: maxX - swW * 0.5,
        z: (minZ + maxZ) * 0.5,
        width: swW,
        depth: actualLotD,
        y: 0.08
      });
    }
    if (cfg.sidewalkConfig === 'full_perimeter') {
      sidewalks.push({
        id: 'sw_left',
        x: minX + swW * 0.5,
        z: (minZ + maxZ) * 0.5,
        width: swW,
        depth: actualLotD,
        y: 0.08
      });
    }
  }

  // Driveways & circulation lanes
  const driveways = [];
  const dw = isIndustrial ? 5.2 : 4.2;
  if (cfg.drivewayPlacement === 'dual' || cfg.drivewayPlacement === 'left') {
    const dx = minX + Math.min(sidePad * 0.75 + 2.2, lotW * 0.25);
    driveways.push({
      id: 'driveway_left',
      x: dx,
      z: maxZ - swW * 0.5,
      width: dw,
      depth: swW + 0.4
    });
    if (placementCtx) {
      registerLaneClearance(placementCtx, {
        id: 'lane_left_entry',
        kind: 'driveway',
        minX: dx - dw * 0.55,
        maxX: dx + dw * 0.55,
        minZ: bd * 0.5 + 0.5,
        maxZ: maxZ
      });
    }
  }
  if (cfg.drivewayPlacement === 'dual' || cfg.drivewayPlacement === 'right') {
    const dx = maxX - Math.min(sidePad * 0.75 + 2.2, lotW * 0.25);
    driveways.push({
      id: 'driveway_right',
      x: dx,
      z: maxZ - swW * 0.5,
      width: dw,
      depth: swW + 0.4
    });
    if (placementCtx) {
      registerLaneClearance(placementCtx, {
        id: 'lane_right_entry',
        kind: 'driveway',
        minX: dx - dw * 0.55,
        maxX: dx + dw * 0.55,
        minZ: bd * 0.5 + 0.5,
        maxZ: maxZ
      });
    }
  }

  // Parking stalls
  const parkingStalls = [];
  const requestedStalls = cfg.includeParking && cfg.parkingConfig !== 'none' ? (cfg.parkingCount || 0) : 0;
  const stallW = 2.6;
  const stallD = 5.0;

  if (requestedStalls > 0 && !isUrban) {
    if (cfg.parkingConfig === 'side_lot' || (cfg.parkingConfig === 'wrap_around' && sidePad >= 5.2)) {
      const sideX = minX + 3.2;
      const maxFit = Math.max(1, Math.floor((actualLotD - swW - 4.0) / stallW));
      const count = Math.min(requestedStalls, maxFit);
      for (let i = 0; i < count; i++) {
        const sz = maxZ - swW - 3.0 - i * stallW;
        parkingStalls.push({
          id: `stall_side_${i}`,
          x: sideX,
          z: sz,
          width: stallD,
          depth: stallW,
          rotationY: Math.PI / 2
        });
        if (placementCtx) {
          registerLaneClearance(placementCtx, {
            id: `stall_zone_side_${i}`,
            kind: 'parking_stall',
            minX: sideX - stallD * 0.5,
            maxX: sideX + stallD * 0.5,
            minZ: sz - stallW * 0.5,
            maxZ: sz + stallW * 0.5
          });
        }
      }
    } else if (cfg.parkingConfig === 'rear_yard' && rearPad >= 5.5) {
      const rz = minZ + 3.0;
      const maxFit = Math.max(1, Math.floor((lotW - 4.0) / stallW));
      const count = Math.min(requestedStalls, maxFit);
      const totalSpan = count * stallW;
      for (let i = 0; i < count; i++) {
        const sx = -totalSpan * 0.5 + (i + 0.5) * stallW;
        parkingStalls.push({
          id: `stall_rear_${i}`,
          x: sx,
          z: rz,
          width: stallW,
          depth: stallD,
          rotationY: 0
        });
      }
    } else if (frontPad >= 6.2) {
      // Front row along sidewalk inner edge (skipping driveway mouths)
      const fz = maxZ - swW - stallD * 0.5 - 0.6;
      const maxFit = Math.max(1, Math.floor((lotW - 6.0) / stallW));
      const count = Math.min(requestedStalls, maxFit);
      const totalSpan = count * stallW;
      for (let i = 0; i < count; i++) {
        const sx = -totalSpan * 0.5 + (i + 0.5) * stallW;
        const hitsDriveway = driveways.some((d) => Math.abs(sx - d.x) < d.width * 0.62);
        if (hitsDriveway) continue;
        parkingStalls.push({
          id: `stall_front_${i}`,
          x: sx,
          z: fz,
          width: stallW,
          depth: stallD,
          rotationY: 0
        });
        if (placementCtx) {
          registerLaneClearance(placementCtx, {
            id: `stall_zone_front_${i}`,
            kind: 'parking_stall',
            minX: sx - stallW * 0.5,
            maxX: sx + stallW * 0.5,
            minZ: fz - stallD * 0.5,
            maxZ: fz + stallD * 0.5
          });
        }
      }
    }
  }

  // Service yard / fenced rear zone
  const serviceYard = cfg.serviceAccess && rearPad >= 3.2 ? {
    id: 'service_yard',
    x: -bw * 0.25,
    z: minZ + Math.min(rearPad * 0.45, 2.2),
    width: Math.min(bw * 0.55, 7.5),
    depth: Math.min(rearPad - 0.9, 3.6),
    fenced: isIndustrial || Boolean(options.fencedServiceYard)
  } : null;

  // Perimeter fence if industrial or secure facility
  const fences = [];
  if (options.fencedPerimeter || options.industrialFence) {
    fences.push({
      id: 'perimeter_fence',
      minX: minX + 0.3,
      maxX: maxX - 0.3,
      minZ: minZ + 0.3,
      maxZ: maxZ - swW - 0.3,
      gateOpenFront: true,
      height: options.fenceHeight || 2.1
    });
  } else if (serviceYard && serviceYard.fenced) {
    fences.push({
      id: 'service_yard_fence',
      minX: serviceYard.x - serviceYard.width * 0.5,
      maxX: serviceYard.x + serviceYard.width * 0.5,
      minZ: serviceYard.z - serviceYard.depth * 0.5,
      maxZ: serviceYard.z + serviceYard.depth * 0.5,
      gateOpenFront: false,
      height: 1.9
    });
  }

  // Landscaping planter strips along front corners
  const landscapingBeds = [];
  if (cfg.includeLandscaping && !isIndustrial) {
    const bedW = Math.min(3.2, Math.max(1.4, sidePad * 0.6));
    const bedD = 1.6;
    const bz = maxZ - swW - bedD * 0.5 - 0.35;
    if (lotW >= bw + 4.5) {
      landscapingBeds.push({ id: 'bed_front_left', x: minX + bedW * 0.5 + 0.5, z: bz, width: bedW, depth: bedD, hasTree: true });
      landscapingBeds.push({ id: 'bed_front_right', x: maxX - bedW * 0.5 - 0.5, z: bz, width: bedW, depth: bedD, hasTree: true });
    }
  }

  // Register standard lot anchors
  if (placementCtx) {
    const swY = 0.08;
    registerAnchor(placementCtx, {
      id: 'sidewalk_front_left',
      category: 'sidewalk',
      position: [-Math.min(bw * 0.42, halfW - 1.5), swY, maxZ - swW * 0.55],
      surfaceY: swY,
      rotationY: 0
    });
    registerAnchor(placementCtx, {
      id: 'sidewalk_front_right',
      category: 'sidewalk',
      position: [Math.min(bw * 0.42, halfW - 1.5), swY, maxZ - swW * 0.55],
      surfaceY: swY,
      rotationY: 0
    });
    registerAnchor(placementCtx, {
      id: 'roadside_sign_corner',
      category: 'roadside',
      position: [maxX - 1.9, 0.08, maxZ - swW - 1.2],
      surfaceY: 0.08,
      rotationY: 0
    });
    registerAnchor(placementCtx, {
      id: 'service_yard_dumpster',
      category: 'service_yard',
      position: [minX + 2.4, 0.02, minZ + 1.8],
      surfaceY: 0.02,
      rotationY: 0
    });
  }

  return {
    enabled: true,
    lotType: cfg.lotType,
    surfaceKind,
    bounds: {
      minX: roundNum(minX, 4),
      maxX: roundNum(maxX, 4),
      minZ: roundNum(minZ, 4),
      maxZ: roundNum(maxZ, 4),
      width: roundNum(lotW, 4),
      depth: roundNum(actualLotD, 4)
    },
    sidewalkWidth: swW,
    sidewalks,
    driveways,
    parkingStalls,
    landscapingBeds,
    fences,
    serviceYard,
    patio: options.patio || null,
    loadingApron: options.loadingApron || null
  };
}

  // --- Module: core/blueprints.js ---
function vecToBGameUnits(x = 0, y = 0, z = 0) {
  return {
    x: roundNum(x * B_UNITS_PER_METER, 3),
    y: roundNum(-z * B_UNITS_PER_METER, 3),
    z: roundNum(y * B_UNITS_PER_METER, 3)
  };
}

function measureBox3(root) {
  let min = { x: 0, y: 0, z: 0 };
  let max = { x: 0, y: 0, z: 0 };
  let meshCount = 0;
  let triangleCount = 0;

  if (root) {
    root.updateMatrixWorld(true);
    root.traverse((obj) => {
      if (!obj.isMesh || !obj.geometry) return;
      meshCount += 1;
      const pos = obj.geometry.attributes?.position;
      const idx = obj.geometry.index;
      if (idx) triangleCount += Math.floor(idx.count / 3);
      else if (pos) triangleCount += Math.floor(pos.count / 3);
    });
    if (meshCount > 0 && typeof THREE !== 'undefined' && THREE.Box3) {
      const box = new THREE.Box3().setFromObject(root);
      if (!box.isEmpty()) {
        min = { x: roundNum(box.min.x, 4), y: roundNum(box.min.y, 4), z: roundNum(box.min.z, 4) };
        max = { x: roundNum(box.max.x, 4), y: roundNum(box.max.y, 4), z: roundNum(box.max.z, 4) };
      }
    }
  }

  return {
    meshCount,
    triangleCount,
    min,
    max,
    size: {
      x: roundNum(Math.max(0, max.x - min.x), 4),
      y: roundNum(Math.max(0, max.y - min.y), 4),
      z: roundNum(Math.max(0, max.z - min.z), 4)
    },
    center: {
      x: roundNum((min.x + max.x) * 0.5, 4),
      y: roundNum((min.y + max.y) * 0.5, 4),
      z: roundNum((min.z + max.z) * 0.5, 4)
    }
  };
}

function generateSpecialtyBlueprint(rawCfg, assemblyData = {}) {
  const settings = sanitiseSpecialtyConfig(rawCfg);
  const fam = getSpecialtyFamily(settings.familyId);
  const preset = getSpecialtyPreset(settings.presetId);

  const buildingStats = measureBox3(assemblyData.layerA);
  const lotStats = measureBox3(assemblyData.layerB);
  const objectsStats = measureBox3(assemblyData.layerC);
  const fullStats = measureBox3(assemblyData.root);

  const identityPayload = JSON.stringify({
    familyId: settings.familyId,
    presetId: settings.presetId,
    seed: settings.seed,
    variationStrength: settings.variationStrength,
    width: settings.width,
    depth: settings.depth,
    floors: settings.floors,
    floorHeight: settings.floorHeight,
    lotType: settings.lotType
  });
  const tplHash = hashBlueprintString(identityPayload).slice(0, 12);
  const revHash = hashBlueprintString(JSON.stringify(settings));

  const anchors = assemblyData.placementCtx
    ? Array.from(assemblyData.placementCtx.anchors.values())
    : [];

  const entrances = (assemblyData.entrances || []).map((e, i) => ({
    id: e.id || `entrance_${i}`,
    role: e.role || 'main',
    label: e.label || 'Public Entrance',
    positionMeters: {
      x: roundNum(e.position?.x || 0, 4),
      y: roundNum(e.position?.y || 0, 4),
      z: roundNum(e.position?.z || 0, 4)
    },
    bGamePosition: vecToBGameUnits(e.position?.x || 0, e.position?.y || 0, e.position?.z || 0),
    normal: e.normal || { x: 0, y: 0, z: 1 },
    widthMeters: roundNum(e.width || 1.8, 3),
    heightMeters: roundNum(e.height || 2.3, 3),
    approachMeters: e.approach || {
      x: roundNum((e.position?.x || 0) + (e.normal?.x || 0) * 1.4, 4),
      y: roundNum(e.position?.y || 0, 4),
      z: roundNum((e.position?.z || 0) + (e.normal?.z || 0) * 1.4, 4)
    }
  }));

  const blueprint = {
    schemaVersion: BLUEPRINT_SCHEMA_VERSION,
    generator: { ...GENERATOR_META },
    templateId: `spec_bldg_${settings.familyId}_${settings.seed}_${tplHash}`,
    templateRevision: `rev_${revHash}`,
    name: String(assemblyData.name || `${preset?.label || fam?.label || settings.familyId} #${settings.seed}`),
    categoryId: fam?.categoryId || 'commercial_services',
    familyId: settings.familyId,
    presetId: settings.presetId,
    purpose: fam?.label || settings.familyId,
    architecturalEra: settings.architecturalEra,
    condition: settings.condition,
    seed: settings.seed,
    settings: copy(settings),
    bounds: {
      fullPropertyMeters: fullStats,
      buildingMeters: buildingStats,
      lotMeters: lotStats,
      bGameUnits: {
        min: vecToBGameUnits(fullStats.min.x, fullStats.min.y, fullStats.max.z),
        max: vecToBGameUnits(fullStats.max.x, fullStats.max.y, fullStats.min.z),
        size: {
          x: roundNum(fullStats.size.x * B_UNITS_PER_METER, 3),
          y: roundNum(fullStats.size.z * B_UNITS_PER_METER, 3),
          z: roundNum(fullStats.size.y * B_UNITS_PER_METER, 3)
        }
      }
    },
    geometryStats: {
      totalTriangles: fullStats.triangleCount,
      totalMeshes: fullStats.meshCount,
      buildingTriangles: buildingStats.triangleCount,
      lotTriangles: lotStats.triangleCount,
      objectsTriangles: objectsStats.triangleCount
    },
    layers: {
      layerA_BuildingStructure: {
        enabled: settings.includeBuildingLayer,
        attachedStructures: assemblyData.attachedStructures || [],
        interiorDisplayZones: assemblyData.interiorDisplayZones || []
      },
      layerB_PropertyLot: assemblyData.lotLayout || { enabled: false, lotType: 'none' },
      layerC_EnvironmentalObjects: {
        enabled: settings.includeObjectsLayer,
        availableGroups: assemblyData.availableObjectGroups || [],
        placedCount: (assemblyData.placedObjects || []).length
      }
    },
    entrances,
    placementAnchors: anchors,
    objectDependencies: assemblyData.placedObjects || [],
    missingObjectDependencies: assemblyData.missingDependencies || [],
    placementDiagnostics: assemblyData.placementCtx?.diagnostics || {
      placedCount: 0,
      nudgedCount: 0,
      rejectedCollisions: [],
      missingDependencies: []
    },
    materials: {
      exteriorMaterial: settings.exteriorMaterial,
      primaryColor: settings.primaryColor,
      secondaryColor: settings.secondaryColor,
      accentColor: settings.accentColor,
      trimColor: settings.trimColor,
      glassColor: settings.glassColor
    }
  };

  return blueprint;
}

function validateSpecialtyBlueprint(data) {
  const errors = [];
  if (!data || typeof data !== 'object') {
    return { valid: false, errors: ['Blueprint payload is not an object'], settings: null };
  }

  // Support both full blueprint and exported settings wrapper
  const candidateSettings = data.settings || data.config || (data.familyId ? data : null);
  if (!candidateSettings || !candidateSettings.familyId) {
    errors.push('Missing familyId in specialty building blueprint/settings');
    return { valid: false, errors, settings: null };
  }

  if (data.schemaVersion && data.schemaVersion !== BLUEPRINT_SCHEMA_VERSION) {
    errors.push(`Unsupported schemaVersion: ${data.schemaVersion}`);
  }

  if (data.schemaVersion === BLUEPRINT_SCHEMA_VERSION) {
    if (!data.templateId) errors.push('Missing templateId');
    if (!data.bounds || !data.bounds.buildingMeters) errors.push('Missing bounds.buildingMeters');
    if (!Array.isArray(data.entrances)) errors.push('Missing entrances array');
    if (!data.layers || !data.layers.layerA_BuildingStructure || !data.layers.layerB_PropertyLot || !data.layers.layerC_EnvironmentalObjects) {
      errors.push('Missing three-layer metadata structure');
    }
  }

  const fam = getSpecialtyFamily(candidateSettings.familyId);
  if (!fam) {
    errors.push(`Unknown specialty building family: ${candidateSettings.familyId}`);
  }

  const sanitised = sanitiseSpecialtyConfig(candidateSettings);
  return {
    valid: errors.length === 0,
    errors,
    settings: sanitised,
    blueprint: data.schemaVersion === BLUEPRINT_SCHEMA_VERSION ? data : null
  };
}

