function applyPreviewMaterialOverrides(root, options = {}) {
  if (!root) return;
  const silhouette = Boolean(options.silhouetteMode);
  const wireframe = Boolean(options.wireframe);
  const clay = getClaySilhouetteMaterial();

  root.traverse((obj) => {
    if (!obj.isMesh) return;
    if (silhouette) {
      if (!obj.userData._origMat) obj.userData._origMat = obj.material;
      obj.material = clay;
    } else if (obj.userData._origMat) {
      obj.material = obj.userData._origMat;
    }
    if (obj.material) {
      obj.material.wireframe = wireframe;
    }
  });
}

  // --- Module: geometry/arch-primitives.js ---
function addBox(parent, x, y, z, w, h, d, material, options = {}) {
  if (w <= 0.001 || h <= 0.001 || d <= 0.001) return null;
  const geo = new THREE.BoxGeometry(w, h, d);
  const mesh = new THREE.Mesh(geo, material);
  mesh.position.set(x, y, z);
  if (options.rotX) mesh.rotation.x = options.rotX;
  if (options.rotY) mesh.rotation.y = options.rotY;
  if (options.rotZ) mesh.rotation.z = options.rotZ;
  mesh.castShadow = options.cast !== false;
  mesh.receiveShadow = options.receive !== false;
  if (options.name) mesh.name = options.name;
  parent.add(mesh);
  return mesh;
}

function addCylinder(parent, x, y, z, rTop, rBottom, h, material, sides = 10, options = {}) {
  if (h <= 0.001) return null;
  const geo = new THREE.CylinderGeometry(rTop, rBottom, h, sides);
  const mesh = new THREE.Mesh(geo, material);
  mesh.position.set(x, y, z);
  if (options.rotX) mesh.rotation.x = options.rotX;
  if (options.rotZ) mesh.rotation.z = options.rotZ;
  mesh.castShadow = options.cast !== false;
  mesh.receiveShadow = options.receive !== false;
  if (options.name) mesh.name = options.name;
  parent.add(mesh);
  return mesh;
}

function addSemicircleArch(parent, x, y, z, radius, depth, material, options = {}) {
  if (radius <= 0.001 || depth <= 0.001) return null;
  const shape = new THREE.Shape();
  shape.absarc(0, 0, radius, 0, Math.PI, false);
  shape.closePath();
  const geo = new THREE.ExtrudeGeometry(shape, {
    depth,
    bevelEnabled: false,
    curveSegments: options.segments || 8
  });
  const mesh = new THREE.Mesh(geo, material);
  mesh.position.set(x, y, z);
  mesh.castShadow = options.cast !== false;
  mesh.receiveShadow = options.receive !== false;
  if (options.name) mesh.name = options.name;
  parent.add(mesh);
  return mesh;
}

function addRoofStructure(parent, x, baseY, z, w, d, cfg) {
  const roofMat = solidMaterial(cfg.trimColor || '#38414a');
  const deckMat = surfaceMaterial('concrete', '#5d6368', cfg.condition, cfg.seed + 13, 2, 2);
  const trimMat = solidMaterial(cfg.secondaryColor || '#4d5863');
  const style = cfg.roofStyle || 'flat';
  const pitchH = clamp(cfg.roofPitchHeight || 1.6, 0.4, 4.5);
  const paraH = clamp(cfg.parapetHeight || 0.42, 0.1, 1.5);

  if (style === 'pitched') {
    // Low-poly stepped gable wedge + fascia trim
    addBox(parent, x, baseY + 0.1, z, w + 0.3, 0.2, d + 0.3, trimMat);
    const steps = 6;
    for (let i = 0; i < steps; i++) {
      const t = i / steps;
      const stepD = (d + 0.2) * (1 - t * 0.9);
      const stepH = (pitchH / steps) + 0.04;
      addBox(parent, x, baseY + 0.2 + (i + 0.5) * (pitchH / steps), z, w + 0.2, stepH, stepD, roofMat);
    }
    return baseY + 0.2 + pitchH;
  }

  if (style === 'hip') {
    addBox(parent, x, baseY + 0.1, z, w + 0.35, 0.2, d + 0.35, trimMat);
    const tiers = 5;
    for (let i = 0; i < tiers; i++) {
      const t = i / tiers;
      const tw = (w + 0.2) * (1 - t * 0.82);
      const td = (d + 0.2) * (1 - t * 0.82);
      const th = (pitchH / tiers) + 0.04;
      addBox(parent, x, baseY + 0.2 + (i + 0.5) * (pitchH / tiers), z, tw, th, td, roofMat);
    }
    return baseY + 0.2 + pitchH;
  }

  if (style === 'mansard') {
    addBox(parent, x, baseY + 0.1, z, w + 0.25, 0.2, d + 0.25, trimMat);
    const tiers = 4;
    for (let i = 0; i < tiers; i++) {
      const t = i / tiers;
      const tw = (w + 0.15) * (1 - t * 0.24);
      const td = (d + 0.15) * (1 - t * 0.24);
      const th = (pitchH * 0.8 / tiers) + 0.03;
      addBox(parent, x, baseY + 0.2 + (i + 0.5) * (pitchH * 0.8 / tiers), z, tw, th, td, roofMat);
    }
    addBox(parent, x, baseY + 0.2 + pitchH * 0.8, z, w * 0.76, 0.12, d * 0.76, deckMat);
    return baseY + 0.2 + pitchH * 0.8 + 0.06;
  }

  if (style === 'shed') {
    const steps = 5;
    for (let i = 0; i < steps; i++) {
      const sd = (d + 0.2) / steps;
      const sz = z - d * 0.5 + (i + 0.5) * sd;
      const sh = 0.22 + ((steps - 1 - i) / steps) * pitchH * 0.7;
      addBox(parent, x, baseY + sh * 0.5, sz, w + 0.2, sh, sd + 0.02, roofMat);
    }
    return baseY + 0.22 + pitchH * 0.7;
  }

  if (style === 'sawtooth') {
    const bays = Math.max(2, Math.round(d / 4.2));
    const bayD = d / bays;
    for (let b = 0; b < bays; b++) {
      const bz = z - d * 0.5 + (b + 0.5) * bayD;
      const steps = 4;
      for (let s = 0; s < steps; s++) {
        const sd = bayD / steps;
        const sz = bz - bayD * 0.5 + (s + 0.5) * sd;
        const sh = 0.2 + ((s + 1) / steps) * (pitchH * 0.75);
        addBox(parent, x, baseY + sh * 0.5, sz, w + 0.1, sh, sd + 0.02, roofMat);
      }
      // Northlight glazing strip
      addBox(parent, x, baseY + pitchH * 0.42, bz + bayD * 0.48, w - 0.3, pitchH * 0.5, 0.08, glassMaterial(cfg.glassColor, cfg.lightingTime === 'night', { lightingTime: cfg.lightingTime }));
    }
    return baseY + pitchH * 0.75 + 0.2;
  }

  if (style === 'stepped') {
    addBox(parent, x, baseY + 0.12, z, w + 0.2, 0.24, d + 0.2, deckMat);
    addBox(parent, x, baseY + 0.24 + paraH * 0.5, z + d * 0.5 - 0.12, w * 0.96, paraH, 0.24, trimMat);
    addBox(parent, x, baseY + 0.24 + paraH + 0.35, z + d * 0.5 - 0.16, w * 0.58, 0.7, 0.28, solidMaterial(cfg.accentColor || '#d9a441'));
    return baseY + 0.24 + paraH + 0.7;
  }

  // Default flat parapet roof
  addBox(parent, x, baseY + 0.1, z, w + 0.16, 0.2, d + 0.16, deckMat);
  const pt = 0.2;
  addBox(parent, x, baseY + 0.2 + paraH * 0.5, z + d * 0.5 - pt * 0.5, w + 0.16, paraH, pt, trimMat);
  addBox(parent, x, baseY + 0.2 + paraH * 0.5, z - d * 0.5 + pt * 0.5, w + 0.16, paraH, pt, trimMat);
  addBox(parent, x - w * 0.5 + pt * 0.5, baseY + 0.2 + paraH * 0.5, z, pt, paraH, d - pt, trimMat);
  addBox(parent, x + w * 0.5 - pt * 0.5, baseY + 0.2 + paraH * 0.5, z, pt, paraH, d - pt, trimMat);
  return baseY + 0.2;
}

function addSignboardUnit(parent, x, y, z, w, h, text, bgHex, fgHex, cfg, options = {}) {
  const g = new THREE.Group();
  g.position.set(x, y, z);
  if (options.rotY) g.rotation.y = options.rotY;
  const frameMat = solidMaterial(cfg.trimColor || '#1d2228');
  addBox(g, 0, 0, 0, w + 0.14, h + 0.14, 0.12, frameMat);
  const lit = cfg.includeIlluminatedSigns !== false;
  const faceMat = signboardMaterial(text, bgHex, fgHex, lit, cfg.lightingTime);
  const face = new THREE.Mesh(new THREE.PlaneGeometry(w, h), faceMat);
  face.position.z = 0.068;
  g.add(face);
  if (options.doubleSided) {
    const back = new THREE.Mesh(new THREE.PlaneGeometry(w, h), faceMat);
    back.position.z = -0.068;
    back.rotation.y = Math.PI;
    g.add(back);
  }
  if (cfg.signageStyle === 'neon_marquee' && lit) {
    const neon = emissiveMaterial(fgHex, 0.9, cfg.lightingTime);
    addBox(g, 0, h * 0.5 + 0.05, 0.06, w + 0.08, 0.04, 0.04, neon);
    addBox(g, 0, -h * 0.5 - 0.05, 0.06, w + 0.08, 0.04, 0.04, neon);
  }
  parent.add(g);
  return g;
}

function addDoorUnit(parent, x, y, z, w, h, cfg, options = {}) {
  const g = new THREE.Group();
  g.position.set(x, y, z);
  if (options.rotY) g.rotation.y = options.rotY;
  const frameMat = solidMaterial(cfg.trimColor || '#262d35');
  const glassMat = glassMaterial(cfg.glassColor, cfg.lightingTime === 'night', {
    lightingTime: cfg.lightingTime,
    transparent: Boolean(options.transparentGlass)
  });
  const handleMat = solidMaterial('#d8dfe6');

  addBox(g, -w * 0.5, h * 0.5, 0.04, 0.09, h, 0.12, frameMat);
  addBox(g, w * 0.5, h * 0.5, 0.04, 0.09, h, 0.12, frameMat);
  addBox(g, 0, h + 0.04, 0.04, w + 0.14, 0.09, 0.14, frameMat);

  if (options.solidDoor) {
    addBox(g, 0, h * 0.5, 0.02, w - 0.08, h - 0.05, 0.07, solidMaterial(options.doorColor || '#46505a'));
    addBox(g, w * 0.34, h * 0.45, 0.07, 0.04, 0.24, 0.04, handleMat);
  } else {
    // Double glass commercial storefront door
    addBox(g, -w * 0.24, h * 0.5, 0.02, w * 0.45, h - 0.08, 0.05, glassMat);
    addBox(g, w * 0.24, h * 0.5, 0.02, w * 0.45, h - 0.08, 0.05, glassMat);
    addBox(g, 0, h * 0.5, 0.03, 0.05, h - 0.06, 0.07, frameMat);
    addBox(g, -0.09, h * 0.45, 0.07, 0.03, 0.42, 0.04, handleMat);
    addBox(g, 0.09, h * 0.45, 0.07, 0.03, 0.42, 0.04, handleMat);
  }

  parent.add(g);
  return g;
}

function addRollUpGarageDoor(parent, x, y, z, w, h, cfg, options = {}) {
  const g = new THREE.Group();
  g.position.set(x, y, z);
  if (options.rotY) g.rotation.y = options.rotY;
  const frameMat = solidMaterial(cfg.trimColor || '#2b323a');
  const doorMat = solidMaterial(options.doorColor || '#98a3ad');
  const slatAccent = solidMaterial(darkenHex(options.doorColor || '#98a3ad', 0.22));
  const openRatio = clamp(options.openRatio ?? 0.0, 0, 0.85);

  addBox(g, -w * 0.5 - 0.07, h * 0.5, 0.06, 0.14, h, 0.18, frameMat);
  addBox(g, w * 0.5 + 0.07, h * 0.5, 0.06, 0.14, h, 0.18, frameMat);
  addBox(g, 0, h + 0.08, 0.06, w + 0.28, 0.16, 0.2, frameMat);

  // Dark bay interior backing for open doors
  addBox(g, 0, h * 0.5, -0.35, w - 0.06, h - 0.04, 0.06, solidMaterial('#181c22'));

  const visibleH = Math.max(0.28, h * (1 - openRatio));
  const doorY = h - visibleH * 0.5;
  addBox(g, 0, doorY, 0.02, w - 0.06, visibleH, 0.06, doorMat);

  const slats = Math.max(2, Math.floor(visibleH / 0.38));
  for (let i = 0; i < slats; i++) {
    const sy = (h - visibleH) + (i + 0.5) * (visibleH / slats);
    addBox(g, 0, sy, 0.055, w - 0.1, 0.03, 0.02, slatAccent);
  }

  // Optional small vision lites near eye level when closed
  if (openRatio < 0.2 && visibleH > 1.8) {
    const glassMat = glassMaterial(cfg.glassColor, cfg.lightingTime === 'night', { lightingTime: cfg.lightingTime });
    const panes = Math.max(2, Math.floor(w / 0.85));
    for (let p = 0; p < panes; p++) {
      const px = -w * 0.34 + (panes > 1 ? (p / (panes - 1)) * (w * 0.68) : 0);
      addBox(g, px, 1.55, 0.058, 0.42, 0.22, 0.02, glassMat);
    }
  }

  parent.add(g);
  return g;
}

function addAwning(parent, x, y, z, w, d, h, colorHexStr, options = {}) {
  const g = new THREE.Group();
  g.position.set(x, y, z);
  if (options.rotY) g.rotation.y = options.rotY;
  const mat = solidMaterial(colorHexStr);
  const stripeMat = solidMaterial(options.stripeColor || lightenHex(colorHexStr, 0.32));
  const steps = 4;
  for (let i = 0; i < steps; i++) {
    const sz = (i + 0.5) * (d / steps);
    const sy = (steps - 1 - i) * (h / steps);
    addBox(g, 0, sy, sz, w, h / steps + 0.02, d / steps + 0.02, mat);
  }
  // Valance flap
  addBox(g, 0, -0.08, d - 0.02, w, 0.18, 0.04, stripeMat);
  parent.add(g);
  return g;
}

function addWindowAdDecals(parent, x, y, z, spanW, spanH, cfg, density = 0.65, seed = 404, options = {}) {
  if (!cfg.includeWindowAds || density <= 0.02) return;
  const g = new THREE.Group();
  g.position.set(x, y, z);
  if (options.rotY) g.rotation.y = options.rotY;

  const count = clamp(Math.round(density * Math.max(2, spanW * 1.45)), 1, 12);
  for (let i = 0; i < count; i++) {
    const u = (i + 0.5) / count;
    const px = -spanW * 0.44 + u * (spanW * 0.88) + (((seed + i * 37) % 11) - 5) * 0.02;
    const py = (((seed + i * 53) % 7) - 3) * 0.04 * clamp(spanH, 0.4, 1.4);
    const pw = clamp(0.46 + ((i * 19) % 5) * 0.06, 0.4, 0.76);
    const ph = clamp(0.62 + ((i * 23) % 4) * 0.08, 0.52, 0.96);
    // Slight increasing Z offset prevents overlapping decals from z-fighting
    const pz = 0.025 + (i % 4) * 0.004;
    const mat = windowAdPosterMaterial(seed + i * 3, cfg.condition);
    const mesh = new THREE.Mesh(new THREE.PlaneGeometry(pw, ph), mat);
    mesh.position.set(px, py, pz);
    g.add(mesh);
  }
  parent.add(g);
}

function addFacadeWindows(parent, side, wallCenterX, wallCenterZ, wallLen, cfg, r, options = {}) {
  const rotMap = { front: 0, back: Math.PI, left: -Math.PI / 2, right: Math.PI / 2 };
  const rotY = rotMap[side] || 0;
  const fh = cfg.floorHeight;
  const frameMat = solidMaterial(cfg.trimColor || '#2b323a');
  const glassMat = glassMaterial(cfg.glassColor, cfg.lightingTime === 'night' || cfg.lightingTime === 'dusk', {
    lightingTime: cfg.lightingTime,
    transparent: Boolean(options.transparentGroundGlass),
    tinted: Boolean(options.tintedGlass)
  });

  const skipZones = options.skipIntervals || [];
  const isBlocked = (u, halfW) => skipZones.some(([a, b]) => u + halfW > a - 0.15 && u - halfW < b + 0.15);

  for (let f = 0; f < cfg.floors; f++) {
    const floorBaseY = f * fh;
    const isGround = f === 0;
    const useStorefront = isGround && (cfg.windowStyle === 'storefront' || options.forceStorefront);
    const density = isGround ? Math.max(0.25, cfg.windowDensity) : cfg.windowDensity;
    if (density <= 0.02) continue;

    const bays = Math.max(1, Math.floor((wallLen - 1.2) / (useStorefront ? 2.6 : 2.1)));
    const bayStep = (wallLen - 1.0) / bays;

    for (let i = 0; i < bays; i++) {
      if (r() > density + 0.18) continue;
      const localX = -(wallLen - 1.0) * 0.5 + (i + 0.5) * bayStep;
      const winW = useStorefront ? Math.min(2.15, bayStep * 0.82) : Math.min(1.28, bayStep * 0.64);
      const winH = useStorefront ? Math.min(fh * 0.68, 2.35) : Math.min(fh * 0.54, 1.58);
      if (isBlocked(localX, winW * 0.55)) continue;

      const winY = floorBaseY + (useStorefront ? 0.35 + winH * 0.5 : fh * 0.52);
      const wx = wallCenterX + Math.cos(rotY) * localX;
      const wz = wallCenterZ - Math.sin(rotY) * localX;
      const outX = Math.sin(rotY) * 0.04;
      const outZ = Math.cos(rotY) * 0.04;

      const g = new THREE.Group();
      g.name = 'WindowUnit';
      g.position.set(wx + outX, winY, wz + outZ);
      g.rotation.y = rotY;

      if (cfg.windowStyle === 'arched') {
        const archR = winW * 0.5;
        const rectH = Math.max(0.45, winH - archR * 0.72);
        const rectOffsetY = -archR * 0.36;
        const archBaseY = rectOffsetY + rectH * 0.5;

        // Lower rectangular frame & sill stopping flush at springline archBaseY (z in [-0.03, +0.05])
        addBox(g, 0, rectOffsetY - 0.035, 0.01, winW + 0.14, rectH + 0.07, 0.08, frameMat);
        addBox(g, 0, rectOffsetY - rectH * 0.5 - 0.06, 0.05, winW + 0.22, 0.08, 0.12, frameMat);
        // Lower rectangular glass stopping flush at springline (z in [+0.02, +0.06])
        addBox(g, 0, rectOffsetY, 0.04, winW, rectH, 0.04, glassMat, { cast: false });

        // Upper semicircular arch frame (y >= archBaseY, z in [-0.03, +0.05]) & fanlight glass (z in [+0.02, +0.06])
        addSemicircleArch(g, 0, archBaseY, -0.03, archR + 0.07, 0.08, frameMat, { name: 'archFrame' });
        addSemicircleArch(g, 0, archBaseY, 0.02, archR, 0.04, glassMat, { cast: false, name: 'archGlass' });

        // Horizontal transom bar proud of glass (z in [+0.062, +0.082])
        addBox(g, 0, archBaseY, 0.072, winW + 0.14, 0.065, 0.02, frameMat);
      } else {
        // Frame + sill + glass
        addBox(g, 0, 0, 0.01, winW + 0.14, winH + 0.14, 0.08, frameMat);
        addBox(g, 0, -winH * 0.5 - 0.06, 0.05, winW + 0.22, 0.08, 0.12, frameMat);
        addBox(g, 0, 0, 0.04, winW, winH, 0.04, glassMat, { cast: false });

        if (cfg.windowStyle === 'barred') {
          for (let b = -2; b <= 2; b++) {
            addBox(g, (b / 2.5) * (winW * 0.45), 0, 0.08, 0.028, winH, 0.028, frameMat);
          }
        } else if (cfg.windowStyle === 'industrial') {
          addBox(g, 0, 0, 0.06, winW, 0.04, 0.03, frameMat);
          addBox(g, 0, 0, 0.062, 0.04, winH, 0.03, frameMat);
        }
      }

      parent.add(g);
    }
  }
}

function addStandardBuildingShell(parent, ctx, options = {}) {
  const { cfg, placementCtx, r } = ctx;
  const w = options.width || cfg.width;
  const d = options.depth || cfg.depth;
  const cx = options.x || 0;
  const cz = options.z || 0;
  const floors = options.floors || cfg.floors;
  const fh = options.floorHeight || cfg.floorHeight;
  const totalH = floors * fh;

  const wallMat = surfaceMaterial(cfg.exteriorMaterial, cfg.primaryColor, cfg.condition, cfg.seed, Math.max(1, Math.round(w / 4)), Math.max(1, floors));
  const plinthMat = solidMaterial(darkenHex(cfg.trimColor || '#38414a', 0.25));
  const trimMat = solidMaterial(cfg.trimColor || '#38414a');

  // Ground plinth + main wall volume + floor belt courses
  addBox(parent, cx, 0.15, cz, w + 0.12, 0.3, d + 0.12, plinthMat);
  addBox(parent, cx, totalH * 0.5, cz, w, totalH, d, wallMat);

  for (let f = 1; f < floors; f++) {
    addBox(parent, cx, f * fh, cz, w + 0.12, 0.14, d + 0.12, trimMat);
  }

  // Corner pilasters
  for (const sx of [-1, 1]) {
    for (const sz of [-1, 1]) {
      addBox(parent, cx + sx * (w * 0.5), totalH * 0.5, cz + sz * (d * 0.5), 0.28, totalH, 0.28, trimMat);
    }
  }

  // Roof
  const roofTopY = addRoofStructure(parent, cx, totalH, cz, w, d, cfg);

  // Main entrance(s)
  const doorW = options.doorWidth || 1.9;
  const doorH = Math.min(fh * 0.72, 2.45);
  const entCount = options.entranceCount || cfg.entranceCount || 1;
  const doorPositions = [];

  if (entCount === 1) {
    let dx = cx;
    if (cfg.entranceLocation === 'front_left') dx = cx - w * 0.26;
    else if (cfg.entranceLocation === 'front_right') dx = cx + w * 0.26;
    doorPositions.push(dx);
  } else {
    for (let i = 0; i < entCount; i++) {
      const dx = cx - w * 0.28 + (entCount > 1 ? (i / (entCount - 1)) * (w * 0.56) : 0);
      doorPositions.push(dx);
    }
  }

  const frontSkips = [];
  const entrances = [];
  doorPositions.forEach((dx, idx) => {
    addDoorUnit(parent, dx, 0, cz + d * 0.5, doorW, doorH, cfg, {
      transparentGlass: Boolean(options.transparentGlass)
    });
    if (options.entranceAwning !== false) {
      addAwning(parent, dx, doorH + 0.35, cz + d * 0.5, doorW + 0.9, 1.15, 0.38, cfg.accentColor);
    }
    frontSkips.push([dx - cx - doorW * 0.65, dx - cx + doorW * 0.65]);
    const ent = {
      id: idx === 0 ? 'main_entrance' : `secondary_entrance_${idx}`,
      role: idx === 0 ? 'main' : 'secondary',
      label: idx === 0 ? 'Main Public Entrance' : `Secondary Entrance ${idx + 1}`,
      position: { x: roundNum(dx, 3), y: 0, z: roundNum(cz + d * 0.5, 3) },
      normal: { x: 0, y: 0, z: 1 },
      width: doorW,
      height: doorH
    };
    entrances.push(ent);
    if (placementCtx) {
      registerEntranceClearance(placementCtx, ent);
      registerAnchor(placementCtx, {
        id: idx === 0 ? 'entrance_main' : `entrance_sec_${idx}`,
        category: 'entrance',
        position: [dx, 0, cz + d * 0.5 + 0.5],
        surfaceY: 0,
        rotationY: 0
      });
    }
  });

  // Service rear door if enabled
  const backSkips = [];
  if (cfg.includeServiceEntrance && !options.skipRearService) {
    const rx = cx + w * 0.24;
    addDoorUnit(parent, rx, 0, cz - d * 0.5, 1.15, 2.15, cfg, { rotY: Math.PI, solidDoor: true });
    backSkips.push([rx - cx - 0.8, rx - cx + 0.8]);
    const servEnt = {
      id: 'service_entrance',
      role: 'service',
      label: 'Rear Service Entrance',
      position: { x: roundNum(rx, 3), y: 0, z: roundNum(cz - d * 0.5, 3) },
      normal: { x: 0, y: 0, z: -1 },
      width: 1.15,
      height: 2.15
    };
    entrances.push(servEnt);
    if (placementCtx) {
      registerEntranceClearance(placementCtx, servEnt);
    }
  }

  // Facade windows on front/back/left/right
  addFacadeWindows(parent, 'front', cx, cz + d * 0.5, w, { ...cfg, floors }, r, {
    skipIntervals: [...frontSkips, ...(options.extraFrontSkips || [])],
    transparentGroundGlass: options.transparentGlass,
    tintedGlass: options.tintedGlass,
    forceStorefront: options.forceStorefront
  });
  addFacadeWindows(parent, 'back', cx, cz - d * 0.5, w, { ...cfg, floors }, r, {
    skipIntervals: [...backSkips, ...(options.extraBackSkips || [])],
    tintedGlass: options.tintedGlass
  });
  if (!options.skipSideWindows) {
    addFacadeWindows(parent, 'left', cx - w * 0.5, cz, d, { ...cfg, floors }, r, {
      skipIntervals: options.extraLeftSkips || [],
      tintedGlass: options.tintedGlass
    });
    addFacadeWindows(parent, 'right', cx + w * 0.5, cz, d, { ...cfg, floors }, r, {
      skipIntervals: options.extraRightSkips || [],
      tintedGlass: options.tintedGlass
    });
  }

  // Fascia sign
  if (options.includeSign !== false && cfg.signageStyle !== 'minimal') {
    const signW = clamp(w * 0.62, 2.4, 9.5);
    const signH = clamp(fh * 0.24, 0.65, 1.15);
    const signY = Math.min(totalH - 0.3, fh + 0.25);
    addSignboardUnit(parent, cx, signY, cz + d * 0.5 + 0.08, signW, signH, cfg.signText, cfg.secondaryColor, '#ffffff', cfg);
  }

  // Register storefront, roof, and wall anchors
  if (placementCtx) {
    registerAnchor(placementCtx, {
      id: 'storefront_left',
      category: 'storefront',
      position: [cx - w * 0.34, 0, cz + d * 0.5 + 0.65],
      surfaceY: 0,
      rotationY: 0
    });
    registerAnchor(placementCtx, {
      id: 'storefront_right',
      category: 'storefront',
      position: [cx + w * 0.34, 0, cz + d * 0.5 + 0.65],
      surfaceY: 0,
      rotationY: 0
    });
    registerAnchor(placementCtx, {
      id: 'wall_rear_utility',
      category: 'wall',
      position: [cx - w * 0.25, 0, cz - d * 0.5 - 0.05],
      surfaceY: 0,
      rotationY: Math.PI
    });
    registerAnchor(placementCtx, {
      id: 'roof_main',
      category: 'roof',
      position: [cx, roofTopY, cz],
      surfaceY: roofTopY,
      rotationY: 0
    });
  }

  return {
    width: w,
    depth: d,
    totalH,
    roofTopY,
    entrances
  };
}

  // --- Module: geometry/lot-mesh.js ---
function buildLotLayerMesh(lotLayout, cfg) {
  const group = new THREE.Group();
  group.name = 'LayerB_PropertyLot';

  if (!lotLayout || !lotLayout.enabled) {
    return group;
  }

  const { bounds, surfaceKind, sidewalks, driveways, parkingStalls, landscapingBeds, fences, serviceYard, patio, loadingApron } = lotLayout;
  const cx = (bounds.minX + bounds.maxX) * 0.5;
  const cz = (bounds.minZ + bounds.maxZ) * 0.5;

  const baseHex = surfaceKind === 'plaza_stone' ? '#b3aba0' : surfaceKind === 'concrete' ? '#8c9298' : '#353a40';
  const baseKind = surfaceKind === 'plaza_stone' ? 'stone' : surfaceKind === 'concrete' ? 'concrete' : 'asphalt';
  const baseMat = surfaceMaterial(baseKind, baseHex, cfg.condition, cfg.seed + 71, Math.max(2, Math.round(bounds.width / 5)), Math.max(2, Math.round(bounds.depth / 5)));

  // Base lot slab
  addBox(group, cx, -0.04, cz, bounds.width, 0.08, bounds.depth, baseMat, { cast: false });

  // Sidewalks & curbs
  const sidewalkMat = surfaceMaterial('concrete', '#b8bec4', cfg.condition, cfg.seed + 83, 4, 1);
  const curbMat = solidMaterial('#99a0a6');
  for (const sw of sidewalks) {
    addBox(group, sw.x, sw.y * 0.5, sw.z, sw.width, sw.y, sw.depth, sidewalkMat, { cast: false });
    // Curb trim along street edge
    if (sw.id === 'sw_front') {
      addBox(group, sw.x, sw.y + 0.02, sw.z + sw.depth * 0.5 - 0.08, sw.width, 0.05, 0.16, curbMat, { cast: false });
    }
  }

  // Driveway aprons (darker asphalt cut across front sidewalk)
  const apronMat = solidMaterial('#2e3338');
  for (const dw of driveways) {
    addBox(group, dw.x, 0.052, dw.z, dw.width, 0.095, dw.depth, apronMat, { cast: false });
  }

  // Parking stall stripes & concrete wheel stops
  const stripeMat = solidMaterial('#e8ecf0');
  const stopMat = solidMaterial('#b0b6bc');
  for (const st of parkingStalls) {
    const g = new THREE.Group();
    g.position.set(st.x, 0.012, st.z);
    g.rotation.y = st.rotationY || 0;
    addBox(g, -st.width * 0.48, 0, 0, 0.08, 0.015, st.depth, stripeMat, { cast: false });
    addBox(g, st.width * 0.48, 0, 0, 0.08, 0.015, st.depth, stripeMat, { cast: false });
    addBox(g, 0, 0.06, -st.depth * 0.36, st.width * 0.65, 0.11, 0.16, stopMat);
    group.add(g);
  }

  // Service yard concrete pad
  if (serviceYard) {
    addBox(group, serviceYard.x, 0.02, serviceYard.z, serviceYard.width, 0.04, serviceYard.depth, sidewalkMat, { cast: false });
  }

  // Loading apron slab
  if (loadingApron) {
    addBox(group, loadingApron.x, 0.025, loadingApron.z, loadingApron.width, 0.05, loadingApron.depth, sidewalkMat, { cast: false });
  }

  // Patio deck
  if (patio) {
    const patioMat = surfaceMaterial('tile', '#a87d56', cfg.condition, cfg.seed + 109, 3, 2);
    addBox(group, patio.x, 0.05, patio.z, patio.width, 0.1, patio.depth, patioMat, { cast: false });
    const railMat = solidMaterial(cfg.trimColor || '#2b323a');
    addBox(group, patio.x, 0.55, patio.z + patio.depth * 0.5 - 0.04, patio.width, 0.06, 0.06, railMat);
    addBox(group, patio.x - patio.width * 0.5 + 0.04, 0.55, patio.z, 0.06, 0.06, patio.depth, railMat);
    addBox(group, patio.x + patio.width * 0.5 - 0.04, 0.55, patio.z, 0.06, 0.06, patio.depth, railMat);
    for (let i = -2; i <= 2; i++) {
      addBox(group, patio.x + (i / 2.2) * (patio.width * 0.46), 0.3, patio.z + patio.depth * 0.5 - 0.04, 0.05, 0.5, 0.05, railMat);
    }
  }

  // Fences (chainlink / industrial security perimeter)
  const postMat = solidMaterial('#5c646d');
  const meshMat = solidMaterial('#77818c');
  for (const fence of fences) {
    const h = fence.height || 1.9;
    const fw = fence.maxX - fence.minX;
    const fd = fence.maxZ - fence.minZ;
    const fcx = (fence.minX + fence.maxX) * 0.5;
    const fcz = (fence.minZ + fence.maxZ) * 0.5;

    // Back, left, right rails + posts
    addBox(group, fcx, h * 0.5, fence.minZ, fw, h, 0.05, meshMat);
    addBox(group, fence.minX, h * 0.5, fcz, 0.05, h, fd, meshMat);
    addBox(group, fence.maxX, h * 0.5, fcz, 0.05, h, fd, meshMat);
    if (!fence.gateOpenFront) {
      addBox(group, fcx, h * 0.5, fence.maxZ, fw, h, 0.05, meshMat);
    } else {
      const wing = Math.max(0.8, fw * 0.25);
      addBox(group, fence.minX + wing * 0.5, h * 0.5, fence.maxZ, wing, h, 0.05, meshMat);
      addBox(group, fence.maxX - wing * 0.5, h * 0.5, fence.maxZ, wing, h, 0.05, meshMat);
    }
    // Posts
    for (let i = 0; i <= 4; i++) {
      const px = fence.minX + (i / 4) * fw;
      addCylinder(group, px, h * 0.52, fence.minZ, 0.04, 0.04, h + 0.08, postMat, 6);
    }
  }

  // Landscaping beds & stylized OSRS low-poly trees/shrubs
  const mulchMat = solidMaterial('#4b382a');
  const leafMat = solidMaterial('#3f7a42');
  const trunkMat = solidMaterial('#6b472b');
  for (const bed of landscapingBeds) {
    addBox(group, bed.x, 0.09, bed.z, bed.width, 0.18, bed.depth, curbMat);
    addBox(group, bed.x, 0.18, bed.z, bed.width - 0.18, 0.06, bed.depth - 0.18, mulchMat, { cast: false });
    if (bed.hasTree) {
      addCylinder(group, bed.x, 0.85, bed.z, 0.11, 0.16, 1.4, trunkMat, 7);
      addCylinder(group, bed.x, 1.85, bed.z, 0.25, 0.92, 1.35, leafMat, 7);
      addCylinder(group, bed.x, 2.55, bed.z, 0.08, 0.62, 0.95, leafMat, 7);
    } else {
      addBox(group, bed.x, 0.42, bed.z, bed.width * 0.58, 0.42, bed.depth * 0.55, leafMat);
    }
  }

  return group;
}

  // --- Module: geometry/building-assembler.js ---
function createSpecialtyBuilding(rawCfg = {}, options = {}) {
  const baseCfg = sanitiseSpecialtyConfig(rawCfg);
  const cfg = options.skipVariation ? baseCfg : applySeedVariation(baseCfg, options.locks || new Set());
  const fam = getSpecialtyFamily(cfg.familyId);
  if (!fam) {
    throw new Error(`Unknown specialty building family: ${cfg.familyId}`);
  }
  const preset = getSpecialtyPreset(cfg.presetId);
  const streams = createBuildingRngStreams(cfg.seed + (options.seedOffset || 0) * 97);

  const root = new THREE.Group();
  root.name = `SpecialtyBuilding_${fam.id}`;

  const layerA = new THREE.Group();
  layerA.name = 'LayerA_BuildingStructure';
  const mainBuildingGroup = new THREE.Group();
  mainBuildingGroup.name = 'MainBuilding';
  const attachedGroup = new THREE.Group();
  attachedGroup.name = 'AttachedStructures';
  layerA.add(mainBuildingGroup);
  layerA.add(attachedGroup);

  const placementCtx = createPlacementContext(cfg);

  const context = {
    cfg,
    family: fam,
    preset,
    streams,
    r: streams.structure,
    root,
    layerA,
    mainBuildingGroup,
    attachedGroup,
    placementCtx,
    entrances: [],
    attachedStructures: [],
    interiorDisplayZones: [],
    lotOptions: {},
    buildingBounds: {
      width: cfg.width,
      depth: cfg.depth,
      height: cfg.floors * cfg.floorHeight
    }
  };

  // Build Layer A (Building Structure)
  if (typeof fam.buildStructure === 'function') {
    fam.buildStructure(context);
  }

  // Register primary footprint & roof bound if family didn't register custom ones
  if (placementCtx.buildingFootprints.length === 0) {
    registerBuildingFootprint(placementCtx, {
      id: 'main_building',
      minX: -context.buildingBounds.width * 0.5,
      maxX: context.buildingBounds.width * 0.5,
      minZ: -context.buildingBounds.depth * 0.5,
      maxZ: context.buildingBounds.depth * 0.5,
      maxY: context.buildingBounds.height
    });
  }
  if (placementCtx.roofBounds.length === 0) {
    const roofY = context.roofTopY || context.buildingBounds.height;
    registerRoofBound(placementCtx, {
      id: 'main_roof',
      minX: -context.buildingBounds.width * 0.5,
      maxX: context.buildingBounds.width * 0.5,
      minZ: -context.buildingBounds.depth * 0.5,
      maxZ: context.buildingBounds.depth * 0.5,
      y: roofY
    });
    if (!placementCtx.anchors.has('roof_main')) {
      registerAnchor(placementCtx, {
        id: 'roof_main',
        category: 'roof',
        position: [0, roofY, 0],
        surfaceY: roofY,
        rotationY: 0
      });
    }
    if (!placementCtx.anchors.has('roof_center')) {
      registerAnchor(placementCtx, {
        id: 'roof_center',
        category: 'roof',
        position: [0, roofY, 0],
        surfaceY: roofY,
        rotationY: 0
      });
    }
  }

  // Build Layer B (Property / Lot)
  const lotLayout = computeLotLayout(cfg, context.buildingBounds, placementCtx, context.lotOptions);
  const layerB = buildLotLayerMesh(lotLayout, cfg);

  // Plan Layer C (Environmental Objects from City Object Suite)
  const objectSpecs = [];
  if (typeof fam.planObjects === 'function') {
    const famSpecs = fam.planObjects(context, lotLayout) || [];
    objectSpecs.push(...famSpecs);
  }

  // Shared contextual objects driven by common checkboxes
  if (cfg.includeRooftopHvac) {
    objectSpecs.push({
      familyId: 'rooftop_hvac',
      presetId: 'commercial_rooftop_hvac_rtu',
      groupKey: 'rooftop_mep',
      anchorId: 'roof_main',
      placementLayer: 'roof',
      localOffset: [-context.buildingBounds.width * 0.2, 0, -context.buildingBounds.depth * 0.12]
    });
  }
  if (cfg.includeRoofAccess) {
    objectSpecs.push({
      familyId: 'rooftop_hvac',
      presetId: 'rooftop_access_stair_headhouse',
      groupKey: 'rooftop_mep',
      anchorId: 'roof_main',
      placementLayer: 'roof',
      localOffset: [context.buildingBounds.width * 0.24, 0, -context.buildingBounds.depth * 0.16]
    });
  }
  if (cfg.includeDumpsters && lotLayout.enabled && lotLayout.serviceYard) {
    objectSpecs.push({
      familyId: 'commercial_dumpster',
      presetId: cfg.condition === 'abandoned' || cfg.condition === 'neglected' ? 'rusted_alley_dumpster' : 'standard_green_dumpster',
      groupKey: 'waste_utility',
      anchorId: 'service_yard_dumpster',
      localOffset: [0, 0, 0]
    });
  }
  if (cfg.includeUtilityPipes) {
    objectSpecs.push({
      familyId: 'exposed_pipes',
      presetId: 'building_wall_pipe_cluster',
      groupKey: 'waste_utility',
      anchorId: 'wall_rear_utility',
      placementLayer: 'wall',
      localOffset: [0, 0, 0]
    });
    objectSpecs.push({
      familyId: 'utility_cabinet',
      presetId: 'street_telecom_cabinet',
      groupKey: 'waste_utility',
      anchorId: 'wall_rear_utility',
      localOffset: [1.65, 0, 0.45],
      minDensity: 0.45
    });
  }
  if (cfg.includeSecurityCameras) {
    objectSpecs.push({
      familyId: 'residential_entry',
      presetId: 'ptz_security_camera_mount',
      groupKey: 'signage_lighting',
      placementLayer: 'wall',
      position: [context.buildingBounds.width * 0.44, Math.min(3.3, cfg.floorHeight * 0.9), context.buildingBounds.depth * 0.5 + 0.05],
      rotationY: 0,
      allowElevated: true
    });
  }
  if (cfg.includeBenches && lotLayout.enabled && lotLayout.sidewalks.length > 0) {
    objectSpecs.push({
      familyId: 'street_bench',
      presetId: cfg.architecturalEra === 'early_20th' || cfg.architecturalEra === '1940s_1950s' ? 'classic_park_wood_bench' : 'downtown_metal_slat_bench',
      groupKey: 'site_amenities',
      anchorId: 'sidewalk_front_left',
      localOffset: [0, 0, 0],
      minDensity: 0.35
    });
  }
  if (cfg.includeOutdoorVending && lotLayout.enabled) {
    objectSpecs.push({
      familyId: 'soda_vending_machines',
      presetId: 'classic_can_soda_vending',
      groupKey: 'site_amenities',
      anchorId: 'storefront_right',
      localOffset: [0, 0, 0],
      minDensity: 0.45
    });
  }
  if (cfg.exteriorLighting && lotLayout.enabled && lotLayout.sidewalks.length > 0) {
    objectSpecs.push({
      familyId: 'streetlight',
      presetId: cfg.architecturalEra === 'early_20th' ? 'heritage_acorn_streetlamp' : 'modern_highway_cobrahead',
      groupKey: 'signage_lighting',
      anchorId: 'sidewalk_front_right',
      localOffset: [1.2, 0, 0],
      rotationY: Math.PI
    });
  }

  const layerCResult = buildLayerCObjects(objectSpecs, placementCtx, cfg, options);

  // Respect layer visibility toggles
  layerA.visible = cfg.includeBuildingLayer !== false;
  layerB.visible = cfg.includeLot !== false && lotLayout.enabled;
  layerCResult.group.visible = cfg.includeObjectsLayer !== false;

  if (cfg.includeBuildingLayer !== false) root.add(layerA);
  if (cfg.includeLot !== false && lotLayout.enabled) root.add(layerB);
  if (cfg.includeObjectsLayer !== false) root.add(layerCResult.group);

  const blueprint = generateSpecialtyBlueprint(cfg, {
    name: options.name,
    root,
    layerA,
    layerB,
    layerC: layerCResult.group,
    entrances: context.entrances,
    attachedStructures: context.attachedStructures,
    interiorDisplayZones: context.interiorDisplayZones,
    lotLayout,
    placementCtx,
    placedObjects: layerCResult.placedRecords,
    missingDependencies: layerCResult.missingDependencies,
    availableObjectGroups: layerCResult.availableGroups
  });

  root.userData = {
    familyId: cfg.familyId,
    presetId: cfg.presetId,
    seed: cfg.seed,
    settings: copy(cfg),
    blueprint,
    placementCtx,
    entrances: blueprint.entrances,
    availableObjectGroups: layerCResult.availableGroups
  };

  return root;
}

  // --- Module: families/automotive.js ---
function buildGasStationStructure(ctx) {
  const { cfg, mainBuildingGroup, attachedGroup, placementCtx } = ctx;
  const w = cfg.width;
  const d = cfg.depth;
  const shell = addStandardBuildingShell(mainBuildingGroup, ctx, {
    width: w,
    depth: d,
    floors: 1,
    floorHeight: cfg.floorHeight,
    forceStorefront: true,
    transparentGlass: Boolean(cfg.interiorDisplay)
  });
  ctx.entrances.push(...shell.entrances);
  ctx.roofTopY = shell.roofTopY;

  // Storefront window advertisement decals (drink, snack, ice, coffee, lottery, open 24h)
  const adDensity = cfg.windowAdDensity !== undefined ? cfg.windowAdDensity : 0.72;
  if (cfg.includeWindowAds && adDensity > 0.02) {
    const leftSpan = Math.max(1.2, w * 0.34);
    const rightSpan = Math.max(1.2, w * 0.34);
    addWindowAdDecals(mainBuildingGroup, -w * 0.28, 1.45, d * 0.5 + 0.08, leftSpan, 1.4, cfg, adDensity, cfg.seed + 11);
    addWindowAdDecals(mainBuildingGroup, w * 0.28, 1.45, d * 0.5 + 0.08, rightSpan, 1.4, cfg, adDensity, cfg.seed + 29);
  }

  // Optional Attached Repair Garage Wing on Right Side
  let rightWingEnd = w * 0.5;
  if (cfg.includeGarageBay) {
    const gw = 5.4;
    const gd = Math.min(d + 1.2, 8.8);
    const gh = Math.max(cfg.floorHeight, 4.1);
    const gx = w * 0.5 + gw * 0.5;
    const gz = -0.2;
    const wallMat = surfaceMaterial(cfg.exteriorMaterial, cfg.primaryColor, cfg.condition, cfg.seed + 31, 2, 1);
    addBox(attachedGroup, gx, gh * 0.5, gz, gw, gh, gd, wallMat);
    addBox(attachedGroup, gx, gh + 0.14, gz, gw + 0.2, 0.28, gd + 0.2, solidMaterial(cfg.trimColor));
    addRollUpGarageDoor(attachedGroup, gx, 0, gz + gd * 0.5, 3.2, 2.8, cfg, { openRatio: 0.45 });
    const gEnt = {
      id: 'gas_garage_bay',
      role: 'garage',
      label: 'Service Garage Bay',
      position: { x: roundNum(gx, 3), y: 0, z: roundNum(gz + gd * 0.5, 3) },
      normal: { x: 0, y: 0, z: 1 },
      width: 3.4,
      height: 2.8
    };
    ctx.entrances.push(gEnt);
    registerEntranceClearance(placementCtx, gEnt);
    registerBuildingFootprint(placementCtx, {
      id: 'attached_garage',
      minX: gx - gw * 0.5,
      maxX: gx + gw * 0.5,
      minZ: gz - gd * 0.5,
      maxZ: gz + gd * 0.5,
      maxY: gh
    });
    ctx.attachedStructures.push({ id: 'attached_garage', type: 'repair_bay', width: gw, depth: gd });
    rightWingEnd = gx + gw * 0.5;
  }

  // Optional Drive-Thru Car Wash Tunnel on Left Side
  if (cfg.includeCarWash) {
    const cw = 4.8;
    const cd = 9.5;
    const ch = 3.9;
    const cx = -w * 0.5 - cw * 0.5 - 0.3;
    const cz = 0;
    const wallMat = surfaceMaterial(cfg.exteriorMaterial, cfg.primaryColor, cfg.condition, cfg.seed + 53, 2, 1);
    addBox(attachedGroup, cx, ch * 0.5, cz, cw, ch, cd, wallMat);
    addBox(attachedGroup, cx, ch + 0.15, cz, cw + 0.2, 0.3, cd + 0.2, solidMaterial(cfg.accentColor));
    addRollUpGarageDoor(attachedGroup, cx, 0, cz + cd * 0.5, 3.1, 2.85, cfg, { openRatio: 0.78 });
    addRollUpGarageDoor(attachedGroup, cx, 0, cz - cd * 0.5, 3.1, 2.85, cfg, { rotY: Math.PI, openRatio: 0.78 });
    addSignboardUnit(attachedGroup, cx, ch - 0.35, cz + cd * 0.5 + 0.12, 3.4, 0.68, 'CAR WASH', cfg.secondaryColor, '#ffffff', cfg);
    registerBuildingFootprint(placementCtx, {
      id: 'car_wash_tunnel',
      minX: cx - cw * 0.5,
      maxX: cx + cw * 0.5,
      minZ: cz - cd * 0.5,
      maxZ: cz + cd * 0.5,
      maxY: ch
    });
    registerLaneClearance(placementCtx, {
      id: 'car_wash_lane',
      kind: 'drive_thru',
      minX: cx - 2.0,
      maxX: cx + 2.0,
      minZ: cz - cd * 0.5 - 3.5,
      maxZ: cz + cd * 0.5 + 4.5
    });
    ctx.attachedStructures.push({ id: 'car_wash_tunnel', type: 'car_wash', width: cw, depth: cd });
  }

  // Fuel Pump Canopy + Columns + Concrete Islands
  const rowCount = clamp(cfg.pumpRowCount || 1, 1, 3);
  const pumpsPerRow = clamp(cfg.pumpCount || 2, 1, 4);
  const canopyW = clamp(cfg.canopyWidth || Math.max(8.5, pumpsPerRow * 3.6 + 2.2), 5.5, 24);
  const canopyD = clamp(cfg.canopyDepth || (rowCount * 3.8 + 1.8), 4.0, 14);
  const canopyH = clamp(cfg.canopyHeight || 4.6, 3.6, 6.8);
  const canopyZ = d * 0.5 + 3.2 + canopyD * 0.5;
  const canopyX = 0;

  const fasciaMat = solidMaterial(cfg.accentColor || '#d93c2b');
  const deckMat = solidMaterial('#eef2f6');
  const colMat = solidMaterial(cfg.secondaryColor || '#2c4a6e');
  const lightMat = emissiveMaterial('#fff2c4', 0.9, cfg.lightingTime);

  // Canopy roof & fascia band
  addBox(attachedGroup, canopyX, canopyH + 0.28, canopyZ, canopyW, 0.56, canopyD, deckMat);
  addBox(attachedGroup, canopyX, canopyH + 0.28, canopyZ + canopyD * 0.5 + 0.04, canopyW + 0.08, 0.42, 0.08, fasciaMat);
  addBox(attachedGroup, canopyX, canopyH + 0.28, canopyZ - canopyD * 0.5 - 0.04, canopyW + 0.08, 0.42, 0.08, fasciaMat);
  addBox(attachedGroup, canopyX - canopyW * 0.5 - 0.04, canopyH + 0.28, canopyZ, 0.08, 0.42, canopyD + 0.08, fasciaMat);
  addBox(attachedGroup, canopyX + canopyW * 0.5 + 0.04, canopyH + 0.28, canopyZ, 0.08, 0.42, canopyD + 0.08, fasciaMat);

  if (cfg.includeIlluminatedSigns !== false) {
    addSignboardUnit(attachedGroup, canopyX, canopyH + 0.28, canopyZ + canopyD * 0.5 + 0.14, Math.min(canopyW * 0.52, 5.4), 0.46, cfg.signText || 'STARFUEL', cfg.secondaryColor, '#ffffff', cfg);
  }

  // Structural canopy columns + recessed LED panels + pump islands
  ctx._pumpAnchors = [];
  for (let rIdx = 0; rIdx < rowCount; rIdx++) {
    const rz = rowCount === 1
      ? canopyZ
      : canopyZ - canopyD * 0.28 + (rIdx / (rowCount - 1)) * (canopyD * 0.56);

    // Reserve drive lane clearance beside each pump row
    registerLaneClearance(placementCtx, {
      id: `fuel_lane_${rIdx}_front`,
      kind: 'fuel_lane',
      minX: canopyX - canopyW * 0.55,
      maxX: canopyX + canopyW * 0.55,
      minZ: rz + 0.85,
      maxZ: rz + 2.4
    });

    // Support columns at ends of each row
    for (const sx of [-1, 1]) {
      const colX = canopyX + sx * (canopyW * 0.36);
      addBox(attachedGroup, colX, canopyH * 0.5, rz, 0.38, canopyH, 0.38, colMat);
      addBox(attachedGroup, colX, 0.48, rz, 0.54, 0.96, 0.54, solidMaterial('#e0a422'));
    }

    // Concrete pump island slab
    const islandW = Math.max(2.6, pumpsPerRow * 3.1);
    addBox(attachedGroup, canopyX, 0.08, rz, islandW, 0.16, 1.15, solidMaterial('#9da4ab'));

    // Canopy downlights above each pump
    for (let p = 0; p < pumpsPerRow; p++) {
      const px = pumpsPerRow === 1
        ? canopyX
        : canopyX - islandW * 0.34 + (p / (pumpsPerRow - 1)) * (islandW * 0.68);
      addBox(attachedGroup, px, canopyH - 0.02, rz, 0.72, 0.05, 0.52, lightMat, { cast: false });
      const anchorId = `fuel_island_${rIdx}_${p}`;
      registerAnchor(placementCtx, {
        id: anchorId,
        category: 'fuel_island',
        position: [px, 0.16, rz],
        surfaceY: 0.16,
        rotationY: 0
      });
      ctx._pumpAnchors.push({ anchorId, px, rz, rIdx, p });
    }
  }

  ctx.attachedStructures.push({
    id: 'fuel_canopy',
    type: 'canopy',
    width: canopyW,
    depth: canopyD,
    height: canopyH,
    rows: rowCount,
    pumpsPerRow
  });

  // Main building footprint
  registerBuildingFootprint(placementCtx, {
    id: 'main_store',
    minX: -w * 0.5,
    maxX: w * 0.5,
    minZ: -d * 0.5,
    maxZ: d * 0.5,
    maxY: cfg.floorHeight
  });

  ctx.buildingBounds = {
    width: Math.max(w, canopyW, rightWingEnd + w * 0.5),
    depth: d,
    height: Math.max(cfg.floorHeight + 0.5, canopyH + 0.6)
  };
  ctx.lotOptions = { rearMargin: 4.5 };
}

function planGasStationObjects(ctx, lotLayout) {
  const { cfg } = ctx;
  const specs = [];
  const pumpPreset = cfg.architecturalEra === '1960s_1970s'
    ? 'retro_1970s_fuel_pump'
    : cfg.architecturalEra === 'retro_futuristic' || cfg.architecturalEra === 'futuristic'
      ? 'futuristic_energy_dispenser'
      : cfg.includeDieselPumps
        ? 'diesel_truck_pump'
        : 'modern_fuel_dispenser';

  for (const pa of (ctx._pumpAnchors || [])) {
    specs.push({
      familyId: 'fuel_station_pump',
      presetId: pumpPreset,
      groupKey: 'fueling',
      anchorId: pa.anchorId,
      localOffset: [0, 0, 0],
      allowInLane: true,
      overrides: { signText: cfg.signText.split(' ')[0] || 'STARFUEL' }
    });
    // Trash bin & windshield caddy beside outer pumps
    if (pa.p === 0) {
      specs.push({
        familyId: 'gas_station_amenities',
        presetId: 'windshield_squeegee_trash_caddy',
        groupKey: 'fueling',
        anchorId: pa.anchorId,
        localOffset: [-1.1, 0, 0],
        allowInLane: true,
        minDensity: 0.35
      });
    }
    // Protective bollards at island ends
    if (pa.p === 0 || pa.p === (cfg.pumpCount - 1)) {
      specs.push({
        familyId: 'bollard_railing',
        presetId: 'heritage_cast_bollard',
        groupKey: 'fueling',
        anchorId: pa.anchorId,
        localOffset: [pa.p === 0 ? -1.45 : 1.45, 0, 0.36],
        allowInLane: true,
        minDensity: 0.4
      });
    }
  }

  // Storefront propane cage & ice freezer
  if (cfg.includePropaneCage) {
    specs.push({
      familyId: 'gas_station_amenities',
      presetId: 'propane_cylinder_exchange_cage',
      groupKey: 'site_amenities',
      anchorId: 'storefront_left',
      localOffset: [-0.9, 0, 0]
    });
  }
  if (cfg.includeIceFreezer) {
    specs.push({
      familyId: 'gas_station_amenities',
      presetId: 'bagged_ice_freezer_box',
      groupKey: 'site_amenities',
      anchorId: 'storefront_left',
      localOffset: [0.85, 0, 0]
    });
  }
  if (cfg.includeAirPump && lotLayout.enabled) {
    specs.push({
      familyId: 'gas_station_amenities',
      presetId: 'air_tire_inflation_station',
      groupKey: 'site_amenities',
      position: [lotLayout.bounds.maxX - 2.2, 0.02, -cfg.depth * 0.25],
      rotationY: -Math.PI / 2
    });
  }
  if (cfg.includeVacuumStation && lotLayout.enabled) {
    specs.push({
      familyId: 'gas_station_amenities',
      presetId: 'coin_car_vacuum_station',
      groupKey: 'site_amenities',
      position: [lotLayout.bounds.maxX - 2.2, 0.02, cfg.depth * 0.25],
      rotationY: -Math.PI / 2
    });
  }
  if (cfg.includeRoadsideSign && lotLayout.enabled) {
    specs.push({
      familyId: 'gas_station_amenities',
      presetId: 'gas_price_pylon_sign',
      groupKey: 'signage_lighting',
      anchorId: 'roadside_sign_corner',
      localOffset: [0, 0, 0],
      overrides: { signText: cfg.signText.split(' ')[0] || 'STARFUEL' }
    });
  }
  if (lotLayout.enabled) {
    specs.push({
      familyId: 'newspaper_box',
      presetId: 'classic_newspaper_honor_box',
      groupKey: 'site_amenities',
      anchorId: 'storefront_right',
      localOffset: [1.1, 0, 0],
      minDensity: 0.55
    });
  }
  if (cfg.includeGarageBay) {
    specs.push({
      familyId: 'auto_garage_equipment',
      presetId: 'stacked_tire_display_rack',
      groupKey: 'service_equipment',
      position: [cfg.width * 0.5 + 5.8, 0.02, 0.8],
      rotationY: Math.PI / 2
    });
  }

  return specs;
}

function buildAutoRepairGarageStructure(ctx) {
  const { cfg, mainBuildingGroup, attachedGroup, placementCtx } = ctx;
  const bays = clamp(cfg.garageBayCount || 3, 1, 5);
  const bayW = clamp(cfg.bayWidth || 4.0, 3.2, 5.2);
  const bayH = clamp(cfg.bayHeight || 3.4, 2.7, 4.6);
  const shopW = Math.max(cfg.width, bays * bayW + 1.8);
  const shopD = cfg.depth;
  const shopH = Math.max(cfg.floorHeight, bayH + 1.1);

  const wallMat = surfaceMaterial(cfg.exteriorMaterial, cfg.primaryColor, cfg.condition, cfg.seed + 19, 3, 1);
  const trimMat = solidMaterial(cfg.trimColor || '#2b323a');
  addBox(mainBuildingGroup, 0, shopH * 0.5, 0, shopW, shopH, shopD, wallMat);
  addBox(mainBuildingGroup, 0, shopH + 0.18, 0, shopW + 0.2, 0.36, shopD + 0.2, trimMat);

  // Garage service bays across front facade
  const openRatio = clamp(cfg.garageDoorOpenRatio ?? 0.4, 0, 0.85);
  for (let i = 0; i < bays; i++) {
    const bx = -((bays - 1) * bayW) * 0.5 + i * bayW;
    addRollUpGarageDoor(mainBuildingGroup, bx, 0, shopD * 0.5, bayW - 0.55, bayH, cfg, { openRatio });
    const bayEnt = {
      id: `garage_bay_${i}`,
      role: 'garage',
      label: `Service Bay ${i + 1}`,
      position: { x: roundNum(bx, 3), y: 0, z: roundNum(shopD * 0.5, 3) },
      normal: { x: 0, y: 0, z: 1 },
      width: bayW - 0.5,
      height: bayH
    };
    ctx.entrances.push(bayEnt);
    registerEntranceClearance(placementCtx, bayEnt);
    registerAnchor(placementCtx, {
      id: `bay_front_${i}`,
      category: 'equipment_frontage',
      position: [bx, 0, shopD * 0.5 + 0.2],
      surfaceY: 0,
      rotationY: 0
    });
  }

  // Attached customer reception office on left side
  if (cfg.includeOfficeWing) {
    const ow = clamp(cfg.officeWidth || 5.2, 3.6, 8.5);
    const od = Math.max(4.5, shopD * 0.72);
    const oh = Math.min(shopH, 3.5);
    const ox = -shopW * 0.5 - ow * 0.5;
    const oz = shopD * 0.5 - od * 0.5;
    const officeShell = addStandardBuildingShell(attachedGroup, ctx, {
      x: ox,
      z: oz,
      width: ow,
      depth: od,
      floors: 1,
      floorHeight: oh,
      entranceCount: 1,
      includeSign: false,
      skipRearService: true,
      forceStorefront: true
    });
    ctx.entrances.push(...officeShell.entrances);
    registerBuildingFootprint(placementCtx, {
      id: 'reception_office',
      minX: ox - ow * 0.5,
      maxX: ox + ow * 0.5,
      minZ: oz - od * 0.5,
      maxZ: oz + od * 0.5,
      maxY: oh
    });
    ctx.attachedStructures.push({ id: 'reception_office', type: 'office_wing', width: ow, depth: od });
  }

  // Overhead shop sign
  addSignboardUnit(mainBuildingGroup, 0, shopH - 0.45, shopD * 0.5 + 0.1, Math.min(shopW * 0.72, 9.5), 0.85, cfg.signText || 'METRO AUTO REPAIR', cfg.secondaryColor, '#ffffff', cfg);

  // Exhaust ventilation stacks on roof
  for (let i = 0; i < Math.min(3, bays); i++) {
    const sx = -shopW * 0.3 + i * (shopW * 0.3);
    addCylinder(mainBuildingGroup, sx, shopH + 0.9, -shopD * 0.25, 0.16, 0.18, 1.3, solidMaterial('#78828c'), 8);
  }

  registerBuildingFootprint(placementCtx, {
    id: 'main_garage',
    minX: -shopW * 0.5,
    maxX: shopW * 0.5,
    minZ: -shopD * 0.5,
    maxZ: shopD * 0.5,
    maxY: shopH
  });

  ctx.roofTopY = shopH + 0.36;
  ctx.buildingBounds = { width: shopW, depth: shopD, height: shopH + 0.4 };
  ctx.lotOptions = { fencedServiceYard: true, rearMargin: 5.0 };
}

function planAutoRepairObjects(ctx, lotLayout) {
  const { cfg } = ctx;
  const specs = [];

  // Hydraulic lift & tool chest visible inside/at open bay or service yard
  specs.push({
    familyId: 'auto_garage_equipment',
    presetId: 'two_post_hydraulic_car_lift',
    groupKey: 'service_equipment',
    position: [0, 0, cfg.depth * 0.5 - 1.6],
    rotationY: 0,
    allowInsideBuilding: true,
    allowInEntrance: true
  });
  specs.push({
    familyId: 'auto_garage_equipment',
    presetId: 'rolling_mechanic_tool_cabinet',
    groupKey: 'service_equipment',
    position: [-cfg.width * 0.42, 0, cfg.depth * 0.5 + 1.15],
    rotationY: 0
  });
  specs.push({
    familyId: 'auto_garage_equipment',
    presetId: 'stacked_tire_display_rack',
    groupKey: 'service_equipment',
    position: [cfg.width * 0.46, 0, cfg.depth * 0.5 + 1.1],
    rotationY: -Math.PI / 4
  });

  if (lotLayout.enabled) {
    specs.push({
      familyId: 'auto_garage_equipment',
      presetId: 'oil_change_drum_cart',
      groupKey: 'service_equipment',
      anchorId: 'service_yard_dumpster',
      localOffset: [2.2, 0, 0]
    });
    specs.push({
      familyId: 'bollard_railing',
      presetId: 'heritage_cast_bollard',
      groupKey: 'site_amenities',
      position: [-cfg.width * 0.48, 0, cfg.depth * 0.5 + 0.55],
      rotationY: 0
    });
    specs.push({
      familyId: 'bollard_railing',
      presetId: 'heritage_cast_bollard',
      groupKey: 'site_amenities',
      position: [cfg.width * 0.48, 0, cfg.depth * 0.5 + 0.55],
      rotationY: 0
    });
  }

  return specs;
}

