let initialized = false;

function ensureSpecialtyBuildingRegistry() {
  if (!initialized) {
    registerAutomotiveFamilies();
    initialized = true;
  }
  return getAllSpecialtyFamilies();
}

  // --- Module: studio/preview.js ---
function disposeSpecialtyGroup(obj) {
  if (!obj) return;
  while (obj.children.length > 0) {
    const child = obj.children[0];
    obj.remove(child);
    disposeSpecialtyGroup(child);
  }
  if (obj.geometry) {
    obj.geometry.dispose();
  }
  if (obj.userData?._ownedMat && obj.material) {
    if (Array.isArray(obj.material)) obj.material.forEach((m) => m.dispose());
    else obj.material.dispose();
  }
}

function makePreviewOwnedMesh(geo, colorHex, options = {}) {
  const mat = new THREE.MeshStandardMaterial({
    color: colorHex,
    roughness: options.roughness !== undefined ? options.roughness : 0.85,
    metalness: options.metalness !== undefined ? options.metalness : 0.08,
    transparent: Boolean(options.transparent),
    opacity: options.opacity !== undefined ? options.opacity : 1.0
  });
  const mesh = new THREE.Mesh(geo, mat);
  mesh.receiveShadow = options.receiveShadow !== false;
  mesh.castShadow = Boolean(options.castShadow);
  mesh.userData = { _ownedMat: true };
  return mesh;
}

function makeScaleHumanFigure(x, y, z) {
  const g = new THREE.Group();
  g.name = 'ScaleReferenceHuman_1_82m';
  const body = { color: '#58b8d9', roughness: 0.72, transparent: true, opacity: 0.88, castShadow: true };
  const pants = { color: '#2b4f61', roughness: 0.8, transparent: true, opacity: 0.88, castShadow: true };

  const legL = makePreviewOwnedMesh(new THREE.BoxGeometry(0.15, 0.9, 0.16), pants.color, pants);
  legL.position.set(-0.1, 0.45, 0);
  g.add(legL);

  const legR = makePreviewOwnedMesh(new THREE.BoxGeometry(0.15, 0.9, 0.16), pants.color, pants);
  legR.position.set(0.1, 0.45, 0);
  g.add(legR);

  const torso = makePreviewOwnedMesh(new THREE.BoxGeometry(0.42, 0.62, 0.22), body.color, body);
  torso.position.set(0, 1.21, 0);
  g.add(torso);

  const head = makePreviewOwnedMesh(new THREE.CylinderGeometry(0.11, 0.11, 0.25, 10), '#d4e9f5', body);
  head.position.set(0, 1.695, 0);
  g.add(head);

  const base = makePreviewOwnedMesh(new THREE.CylinderGeometry(0.35, 0.37, 0.025, 16), '#346982', { roughness: 0.75, transparent: true, opacity: 0.7 });
  base.position.set(0, 0.0125, 0);
  g.add(base);

  g.position.set(x, y, z);
  return g;
}

function rebuildBlueprintDebugOverlay(debugGroup, buildingGroup, showGizmos) {
  disposeSpecialtyGroup(debugGroup);
  if (!showGizmos || !buildingGroup) return;

  const bp = buildingGroup.userData?.blueprint;
  if (!bp) return;

  // Entrance arrows + clearance plates
  for (const ent of (bp.entrances || [])) {
    const color = ent.role === 'emergency' ? '#ff3838' : ent.role === 'garage' || ent.role === 'loading_dock' ? '#f59e0b' : '#22c55e';
    const ex = ent.position?.x || 0;
    const ey = (ent.position?.y || 0) + 0.06;
    const ez = ent.position?.z || 0;
    const nx = ent.normal?.x || 0;
    const nz = ent.normal?.z || 0;

    const pad = makePreviewOwnedMesh(new THREE.BoxGeometry(ent.width || 2.0, 0.06, 0.8), color, { transparent: true, opacity: 0.65 });
    pad.position.set(ex + nx * 0.6, ey, ez + nz * 0.6);
    debugGroup.add(pad);
  }

  // Placement anchor pins (green = used or open)
  for (const anchor of (bp.placementAnchors || [])) {
    const pin = makePreviewOwnedMesh(new THREE.CylinderGeometry(0.16, 0.04, 0.45, 8), '#38bdf8', { transparent: true, opacity: 0.85 });
    pin.position.set(anchor.position.x, (anchor.position.y || 0) + 0.25, anchor.position.z);
    debugGroup.add(pin);
  }
}

function createSpecialtyPreview(canvasEl) {
  const renderer = new THREE.WebGLRenderer({ canvas: canvasEl, antialias: true, preserveDrawingBuffer: true });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = THREE.PCFSoftShadowMap;
  renderer.outputEncoding = THREE.sRGBEncoding;

  const scene = new THREE.Scene();
  scene.background = new THREE.Color('#131b26');

  const camera = new THREE.PerspectiveCamera(45, 1.5, 0.2, 560);
  camera.position.set(22, 16, 26);

  const controls = new THREE.OrbitControls(camera, canvasEl);
  controls.enableDamping = true;
  controls.dampingFactor = 0.08;
  controls.maxPolarAngle = Math.PI * 0.495;
  controls.minDistance = 4;
  controls.maxDistance = 210;
  controls.target.set(0, 2.5, 0);

  // Lights
  const hemiLight = new THREE.HemisphereLight('#d6e7ff', '#28303b', 0.72);
  scene.add(hemiLight);

  const sunLight = new THREE.DirectionalLight('#fff2dc', 1.15);
  sunLight.position.set(34, 48, 32);
  sunLight.castShadow = true;
  sunLight.shadow.mapSize.width = 2048;
  sunLight.shadow.mapSize.height = 2048;
  sunLight.shadow.camera.near = 2;
  sunLight.shadow.camera.far = 190;
  sunLight.shadow.camera.left = -56;
  sunLight.shadow.camera.right = 56;
  sunLight.shadow.camera.top = 56;
  sunLight.shadow.camera.bottom = -56;
  sunLight.shadow.bias = -0.0005;
  scene.add(sunLight);

  const rimLight = new THREE.DirectionalLight('#85b6ff', 0.38);
  rimLight.position.set(-22, 18, -24);
  scene.add(rimLight);

  // Subtle distant backdrop road + ground plane
  const stageGroup = new THREE.Group();
  stageGroup.name = 'PreviewStageGround';
  const groundMesh = makePreviewOwnedMesh(new THREE.PlaneGeometry(260, 260), '#1b232e', { roughness: 0.96, metalness: 0.02 });
  groundMesh.rotation.x = -Math.PI / 2;
  groundMesh.position.y = -0.02;
  stageGroup.add(groundMesh);

  const gridHelper = new THREE.GridHelper(140, 70, '#2e3e52', '#222d3b');
  gridHelper.position.y = -0.01;
  stageGroup.add(gridHelper);
  scene.add(stageGroup);

  const modelRoot = new THREE.Group();
  modelRoot.name = 'SpecialtyModelRoot';
  scene.add(modelRoot);

  const scaleHumanGroup = new THREE.Group();
  scaleHumanGroup.name = 'PreviewScaleHumanGroup';
  scene.add(scaleHumanGroup);

  const debugGizmoGroup = new THREE.Group();
  debugGizmoGroup.name = 'PreviewBlueprintGizmos';
  scene.add(debugGizmoGroup);

  let currentModel = null;
  let turntable = false;
  let turntableSpeed = 0.28;
  let showGrid = true;
  let showScaleHuman = true;
  let showGizmos = false;
  let wireframe = false;
  let silhouette = false;
  let lastFrameTime = performance.now();

  function resize() {
    const parent = canvasEl.parentElement;
    if (!parent) return;
    const w = Math.max(200, parent.clientWidth);
    const h = Math.max(200, parent.clientHeight);
    renderer.setSize(w, h, false);
    camera.aspect = w / h;
    camera.updateProjectionMatrix();
  }

  function applyLightingPreset(timeOfDay = 'day') {
    if (timeOfDay === 'night') {
      scene.background.set('#0b1019');
      hemiLight.color.set('#385380');
      hemiLight.groundColor.set('#0e131b');
      hemiLight.intensity = 0.42;
      sunLight.color.set('#7aa4db');
      sunLight.intensity = 0.52;
      sunLight.position.set(-18, 28, 18);
      rimLight.intensity = 0.55;
    } else if (timeOfDay === 'dusk') {
      scene.background.set('#231d2b');
      hemiLight.color.set('#f4a27e');
      hemiLight.groundColor.set('#22212e');
      hemiLight.intensity = 0.62;
      sunLight.color.set('#ff8f5c');
      sunLight.intensity = 1.05;
      sunLight.position.set(-28, 16, 20);
      rimLight.intensity = 0.48;
    } else if (timeOfDay === 'overcast') {
      scene.background.set('#27313d');
      hemiLight.color.set('#cfdbe8');
      hemiLight.groundColor.set('#333942');
      hemiLight.intensity = 0.92;
      sunLight.color.set('#dde5ed');
      sunLight.intensity = 0.65;
      sunLight.position.set(16, 38, 18);
      rimLight.intensity = 0.3;
    } else {
      scene.background.set('#141d29');
      hemiLight.color.set('#d6e7ff');
      hemiLight.groundColor.set('#29313c');
      hemiLight.intensity = 0.74;
      sunLight.color.set('#fff3df');
      sunLight.intensity = 1.18;
      sunLight.position.set(26, 36, 24);
      rimLight.intensity = 0.36;
    }
  }

  function applyRenderModes() {
    if (!currentModel) return;
    currentModel.traverse((child) => {
      if (!child.isMesh || !child.material) return;
      const mats = Array.isArray(child.material) ? child.material : [child.material];
      for (const m of mats) {
        m.wireframe = Boolean(wireframe);
        if (silhouette) {
          if (m.userData && m.userData._origColorHex === undefined && m.color) {
            m.userData._origColorHex = m.color.getHex();
          }
          if (m.color) m.color.set('#0b0e12');
          if (m.emissive) m.emissive.set('#000000');
        } else if (m.userData && m.userData._origColorHex !== undefined && m.color) {
          m.color.setHex(m.userData._origColorHex);
          delete m.userData._origColorHex;
        }
      }
    });
  }

  function setModel(buildingGroup, cfg) {
    if (currentModel) {
      modelRoot.remove(currentModel);
      disposeSpecialtyGroup(currentModel);
    }
    currentModel = buildingGroup;
    modelRoot.add(buildingGroup);

    applyLightingPreset(cfg?.lightingTime || 'day');
    applyRenderModes();

    // Update scale human beside main entrance sidewalk
    disposeSpecialtyGroup(scaleHumanGroup);
    if (showScaleHuman) {
      const dims = buildingGroup.userData?.blueprint?.bounds?.buildingMeters?.size;
      const hx = -(dims?.x || 8) * 0.5 - 1.2;
      const hz = (dims?.z || 6) * 0.5 + 1.5;
      scaleHumanGroup.add(makeScaleHumanFigure(hx, 0.08, hz));
    }

    rebuildBlueprintDebugOverlay(debugGizmoGroup, buildingGroup, showGizmos);
  }

  function frameCamera(mode = 'full') {
    if (!currentModel) return;
    const box = new THREE.Box3().setFromObject(currentModel);
    if (box.isEmpty()) return;

    const size = new THREE.Vector3();
    const center = new THREE.Vector3();
    box.getSize(size);
    box.getCenter(center);

    const span = Math.max(size.x, size.z, size.y * 1.4, 8);
    if (mode === 'street') {
      controls.target.set(center.x, Math.max(1.8, size.y * 0.25), center.z + size.z * 0.12);
      camera.position.set(center.x + span * 0.45, Math.max(3.2, size.y * 0.35), center.z + span * 0.92);
    } else if (mode === 'roof') {
      controls.target.set(center.x, center.y, center.z);
      camera.position.set(center.x + span * 0.32, span * 1.25, center.z + span * 0.32);
    } else if (mode === 'building') {
      const layerA = currentModel.getObjectByName('LayerA_BuildingStructure');
      if (layerA) {
        const bBox = new THREE.Box3().setFromObject(layerA);
        bBox.getSize(size);
        bBox.getCenter(center);
      }
      const bSpan = Math.max(size.x, size.z, size.y * 1.3, 6);
      controls.target.set(center.x, center.y * 0.85, center.z);
      camera.position.set(center.x + bSpan * 0.85, bSpan * 0.62, center.z + bSpan * 0.95);
    } else {
      controls.target.set(center.x, center.y * 0.72, center.z);
      camera.position.set(center.x + span * 0.82, span * 0.58, center.z + span * 0.94);
    }
    controls.update();
  }

  function animate(now) {
    requestAnimationFrame(animate);
    const dt = Math.min(0.08, (now - lastFrameTime) / 1000);
    lastFrameTime = now;
    if (turntable && currentModel) {
      modelRoot.rotation.y += turntableSpeed * dt;
      debugGizmoGroup.rotation.y = modelRoot.rotation.y;
      scaleHumanGroup.rotation.y = modelRoot.rotation.y;
    }
    controls.update();
    renderer.render(scene, camera);
  }

  resize();
  window.addEventListener('resize', resize);
  requestAnimationFrame(animate);

  return {
    renderer,
    scene,
    camera,
    controls,
    resize,
    setModel,
    frameCamera,
    applyLightingPreset,
    setTurntable(enabled, speed = 0.28) {
      turntable = Boolean(enabled);
      turntableSpeed = clamp(speed, 0.05, 1.5);
      if (!turntable) {
        modelRoot.rotation.y = 0;
        debugGizmoGroup.rotation.y = 0;
        scaleHumanGroup.rotation.y = 0;
      }
    },
    setGridVisible(v) {
      showGrid = Boolean(v);
      gridHelper.visible = showGrid;
    },
    setScaleHumanVisible(v) {
      showScaleHuman = Boolean(v);
      scaleHumanGroup.visible = showScaleHuman;
    },
    setGizmosVisible(v) {
      showGizmos = Boolean(v);
      rebuildBlueprintDebugOverlay(debugGizmoGroup, currentModel, showGizmos);
    },
    setWireframe(v) {
      wireframe = Boolean(v);
      applyRenderModes();
    },
    setSilhouette(v) {
      silhouette = Boolean(v);
      applyRenderModes();
    },
    captureSnapshot(cfg) {
      renderer.render(scene, camera);
      const url = canvasEl.toDataURL('image/png');
      const a = document.createElement('a');
      a.href = url;
      a.download = `specialty-${slugify(cfg?.presetId || cfg?.familyId || 'building')}-${cfg?.seed || 1}.png`;
      document.body.appendChild(a);
      a.click();
      a.remove();
    }
  };
}

  // --- Module: studio/export.js ---
const SPECIALTY_STORAGE_KEY = 'b.specialtyBuildingSuite.savedConfigs.v1';

function triggerDownload(blob, filename) {
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1200);
}

function buildScopedExportRoot(buildingGroup, state = {}) {
  const scope = state.exportScope || 'complete_property';
  const wrap = new THREE.Group();
  wrap.name = `SpecialtyBuildingExport_${slugify(state.presetId || state.familyId || 'building')}`;

  const layerA = buildingGroup.getObjectByName('LayerA_BuildingStructure');
  const layerB = buildingGroup.getObjectByName('LayerB_PropertyLot');
  const layerC = buildingGroup.getObjectByName('LayerC_EnvironmentalObjects');

  if (scope === 'building_only') {
    const mainBlock = buildingGroup.getObjectByName('MainBuilding');
    if (mainBlock) wrap.add(mainBlock.clone(true));
    else if (layerA) wrap.add(layerA.clone(true));
  } else if (scope === 'building_and_attached' || scope === 'building') {
    if (layerA) wrap.add(layerA.clone(true));
  } else if (scope === 'building_and_objects') {
    if (layerA) wrap.add(layerA.clone(true));
    if (layerC) wrap.add(layerC.clone(true));
  } else if (scope === 'lot') {
    if (layerB) wrap.add(layerB.clone(true));
  } else if (scope === 'objects') {
    if (layerC) wrap.add(layerC.clone(true));
  } else {
    for (const child of buildingGroup.children) {
      wrap.add(child.clone(true));
    }
  }

  // Optional coordinate & scale transforms for B Remastered vs standard metric Y-up
  if (state.exportUnits === 'b_units') {
    wrap.scale.setScalar(B_UNITS_PER_METER);
  }
  if (state.exportAxis === 'z_up') {
    wrap.rotation.x = Math.PI / 2;
  }
  wrap.updateMatrixWorld(true);
  return wrap;
}

function exportSpecialtyGLB(buildingGroup, state, toast) {
  if (!buildingGroup) {
    if (toast) toast('Nothing To Export Yet');
    return;
  }
  if (typeof THREE === 'undefined' || !THREE.GLTFExporter) {
    if (toast) toast('Gltf Exporter Not Available');
    return;
  }

  const exportRoot = buildScopedExportRoot(buildingGroup, state);
  const exporter = new THREE.GLTFExporter();
  const scopeSuffix = state.exportScope && state.exportScope !== 'complete_property' ? `-${state.exportScope}` : '';
  const baseName = `specialty-${slugify(state.presetId || state.familyId || 'building')}${scopeSuffix}-${state.seed || 1}`;

  try {
    exporter.parse(
      exportRoot,
      (result) => {
        if (result instanceof ArrayBuffer) {
          const blob = new Blob([result], { type: 'model/gltf-binary' });
          triggerDownload(blob, `${baseName}.glb`);
          if (toast) toast(`Exported ${baseName}.glb`);
        } else {
          const json = JSON.stringify(result, null, 2);
          const blob = new Blob([json], { type: 'application/json' });
          triggerDownload(blob, `${baseName}.gltf`);
          if (toast) toast(`Exported ${baseName}.gltf`);
        }
      },
      { binary: true, onlyVisible: true }
    );
  } catch (err) {
    console.error('Glb Export Error:', err);
    if (toast) toast('Glb Export Failed');
  }
}

function exportSpecialtyBlueprint(buildingGroup, state, toast) {
  const bp = buildingGroup?.userData?.blueprint || generateSpecialtyBlueprint(state, buildingGroup, buildingGroup?.userData?.placementCtx, {
    entrances: buildingGroup?.userData?.entrances || [],
    objectPlacements: buildingGroup?.userData?.objectPlacements || [],
    missingDependencies: buildingGroup?.userData?.missingDependencies || []
  });
  const baseName = `specialty-${slugify(state.presetId || state.familyId || 'building')}-${state.seed || 1}`;
  const blob = new Blob([JSON.stringify(bp, null, 2)], { type: 'application/json' });
  triggerDownload(blob, `${baseName}.specialty.json`);
  if (toast) toast(`Exported ${baseName}.specialty.json`);
  return bp;
}

function exportSpecialtySettings(state, toast) {
  const payload = copy(sanitiseSpecialtyConfig(state));
  const baseName = `specialty-preset-${slugify(state.presetId || state.familyId || 'building')}-${state.seed || 1}`;
  const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
  triggerDownload(blob, `${baseName}.json`);
  if (toast) toast(`Exported ${baseName}.json`);
  return payload;
}

function loadSavedSpecialtyConfigs() {
  try {
    const raw = typeof localStorage !== 'undefined' ? localStorage.getItem(SPECIALTY_STORAGE_KEY) : null;
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch (_) {
    return [];
  }
}

function saveSpecialtyConfig(name, state) {
  const list = loadSavedSpecialtyConfigs();
  const fam = getSpecialtyFamily(state.familyId);
  const entry = {
    id: `saved_${Date.now()}`,
    name: name || `${fam?.label || state.familyId} #${list.length + 1}`,
    savedAt: new Date().toISOString(),
    config: sanitiseSpecialtyConfig(state)
  };
  list.unshift(entry);
  const trimmed = list.slice(0, 25);
  try {
    if (typeof localStorage !== 'undefined') {
      localStorage.setItem(SPECIALTY_STORAGE_KEY, JSON.stringify(trimmed));
    }
  } catch (_) {
    // Ignore storage quota errors
  }
  return entry;
}

function deleteSavedSpecialtyConfig(id) {
  const next = loadSavedSpecialtyConfigs().filter((item) => item.id !== id);
  try {
    if (typeof localStorage !== 'undefined') {
      localStorage.setItem(SPECIALTY_STORAGE_KEY, JSON.stringify(next));
    }
  } catch (_) {}
  return next;
}

function parseImportedSpecialtyJson(rawText) {
  const data = JSON.parse(rawText);
  if (data && (data.schemaVersion === 'b.specialty-building.v1' || data.settings)) {
    const checked = validateSpecialtyBlueprint(data);
    if (!checked.valid) {
      throw new Error(checked.errors.join('; '));
    }
    return { kind: 'blueprint', settings: checked.settings, blueprint: checked.blueprint };
  }
  return { kind: 'settings', settings: sanitiseSpecialtyConfig(data) };
}

  // --- Module: studio/controls.js ---
function escapeHtml(str) {
  return String(str ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function titleTagLabel(tag) {
  return String(tag || '')
    .split('_')
    .map((w) => (w ? w[0].toUpperCase() + w.slice(1) : ''))
    .join(' ');
}

function createSpecialtyControls(studioApi) {
  const {
    state,
    locks,
    onStateChange,
    onSelectPreset,
    onSelectFamily,
    onRandomizeSeed,
    onRandomizeAll,
    onResetPreset,
    onExportGLB,
    onExportBlueprint,
    onExportSettings,
    onImportParsed,
    toast
  } = studioApi;

  let activeCategory = 'all';
  let activeEnvTag = '';
  let searchQuery = '';
  let activeTab = 'structure';

  const categorySelectEl = $('#spec-category-select');
  const envSelectEl = $('#spec-env-select');
  const searchInputEl = $('#spec-search-input');
  const familyListEl = $('#spec-family-list');
  const presetGridEl = $('#spec-preset-grid');
  const presetCountEl = $('#spec-preset-count');
  const seedInputEl = $('#spec-seed-input');
  const varStrengthEl = $('#spec-variation-select');
  const savedListEl = $('#spec-saved-list');
  const tabsBarEl = $('#spec-tabs-bar');
  const tabContentEl = $('#spec-tab-content');

  // Layer quick checkboxes in left bar
  const chkLayerA = $('#spec-toggle-layer-a');
  const chkLayerB = $('#spec-toggle-layer-b');
  const chkLayerC = $('#spec-toggle-layer-c');

  function populateStaticFilters() {
    if (categorySelectEl) {
      categorySelectEl.innerHTML = BUILDING_CATEGORIES.map((cat) => (
        `<option value="${escapeHtml(cat.id)}">${escapeHtml(cat.label)}</option>`
      )).join('');
      categorySelectEl.value = activeCategory;
    }
    if (envSelectEl) {
      envSelectEl.innerHTML = `<option value="">All Environments</option>` +
        ENVIRONMENT_TAGS.map((t) => `<option value="${escapeHtml(t)}">${escapeHtml(titleTagLabel(t))}</option>`).join('');
      envSelectEl.value = activeEnvTag;
    }
    if (varStrengthEl) {
      varStrengthEl.innerHTML = VARIATION_STRENGTHS.map((v) => (
        `<option value="${escapeHtml(v.id)}">${escapeHtml(v.label)}</option>`
      )).join('');
      varStrengthEl.value = state.variationStrength || 'subtle';
    }
  }

  function renderCatalog() {
    const matches = searchSpecialtyCatalog(searchQuery, {
      categoryId: activeCategory,
      environmentTag: activeEnvTag || undefined
    });

    if (familyListEl) {
      const prevFamilyScroll = familyListEl.scrollTop;
      if (matches.length === 0) {
        familyListEl.innerHTML = '<div class="spec-empty-note">No matching building families found.</div>';
      } else {
        familyListEl.innerHTML = matches.map((fam) => {
          const isCurrent = fam.id === state.familyId;
          return `
            <button type="button" class="spec-family-card ${isCurrent ? 'is-active' : ''}" data-family-id="${escapeHtml(fam.id)}">
              <div class="spec-family-title">${escapeHtml(fam.label)}</div>
              <div class="spec-family-meta">${fam.presets.length} Presets</div>
            </button>
          `;
        }).join('');

        $$('.spec-family-card', familyListEl).forEach((btn) => {
          btn.addEventListener('click', () => {
            onSelectFamily(btn.dataset.familyId);
          });
        });
      }
      familyListEl.scrollTop = prevFamilyScroll;
    }

    const activeFam = getSpecialtyFamily(state.familyId) || getAllSpecialtyFamilies()[0];
    if (presetGridEl && activeFam) {
      const prevPresetScroll = presetGridEl.scrollTop;
      const sameFamily = presetGridEl.dataset.renderedFamilyId === activeFam.id;
      presetGridEl.dataset.renderedFamilyId = activeFam.id;
      if (presetCountEl) presetCountEl.textContent = `${activeFam.presets.length} Presets`;
      presetGridEl.innerHTML = activeFam.presets.map((preset) => {
        const isCurrent = preset.id === state.presetId;
        return `
          <button type="button" class="spec-preset-btn ${isCurrent ? 'is-active' : ''}" data-preset-id="${escapeHtml(preset.id)}">
            ${escapeHtml(preset.label)}
          </button>
        `;
      }).join('');

      $$('.spec-preset-btn', presetGridEl).forEach((btn) => {
        btn.addEventListener('click', () => {
          onSelectPreset(btn.dataset.presetId);
        });
      });
      presetGridEl.scrollTop = sameFamily ? prevPresetScroll : 0;
    }
  }

  function renderSavedConfigs() {
    if (!savedListEl) return;
    const saved = loadSavedSpecialtyConfigs();
    if (!saved.length) {
      savedListEl.innerHTML = '<div class="spec-empty-note">No saved buildings yet.</div>';
      return;
    }
    savedListEl.innerHTML = saved.map((entry) => `
      <div class="spec-saved-row">
        <button type="button" class="spec-saved-load" data-load-id="${escapeHtml(entry.id)}">${escapeHtml(entry.name)}</button>
        <button type="button" class="spec-saved-del" data-del-id="${escapeHtml(entry.id)}" title="Delete Saved Config"><i class="fas fa-trash"></i></button>
      </div>
    `).join('');

    $$('.spec-saved-load', savedListEl).forEach((btn) => {
      btn.addEventListener('click', () => {
        const found = loadSavedSpecialtyConfigs().find((item) => item.id === btn.dataset.loadId);
        if (found) {
          onImportParsed({ kind: 'settings', settings: found.config });
          toast(`Loaded "${found.name}"`);
        }
      });
    });

    $$('.spec-saved-del', savedListEl).forEach((btn) => {
      btn.addEventListener('click', () => {
        deleteSavedSpecialtyConfig(btn.dataset.delId);
        renderSavedConfigs();
      });
    });
  }

  function renderTabsBar() {
    if (!tabsBarEl) return;
    tabsBarEl.innerHTML = SHARED_CONTROL_TABS.map((tab) => `
      <button type="button" class="spec-tab-btn ${tab.id === activeTab ? 'is-active' : ''}" data-tab-id="${escapeHtml(tab.id)}">
        <i class="fas ${escapeHtml(tab.icon)}"></i>
        <span>${escapeHtml(tab.label)}</span>
      </button>
    `).join('');

    $$('.spec-tab-btn', tabsBarEl).forEach((btn) => {
      btn.addEventListener('click', () => {
        activeTab = btn.dataset.tabId;
        renderTabsBar();
        renderTabBody();
      });
    });
  }

  function buildFieldHtml(field) {
    const val = state[field.key];
    const isLocked = locks.has(field.key);
    const lockBtn = `<button type="button" class="spec-lock-btn ${isLocked ? 'is-locked' : ''}" data-lock-key="${escapeHtml(field.key)}" title="Lock Parameter Across Presets"><i class="fas ${isLocked ? 'fa-lock' : 'fa-unlock'}"></i></button>`;

    if (field.type === 'boolean') {
      return `
        <div class="spec-field-row spec-field-check">
          <label class="spec-check-label">
            <input type="checkbox" data-field-key="${escapeHtml(field.key)}" data-field-type="boolean" ${val ? 'checked' : ''} />
            <span>${escapeHtml(field.label)}</span>
          </label>
          ${lockBtn}
        </div>
      `;
    }

    if (field.type === 'select') {
      const opts = (field.options || []).map((opt) => {
        const optId = Array.isArray(opt) ? opt[0] : opt.id;
        const optLabel = Array.isArray(opt) ? opt[1] : opt.label;
        return `<option value="${escapeHtml(optId)}" ${val === optId ? 'selected' : ''}>${escapeHtml(optLabel)}</option>`;
      }).join('');
      return `
        <div class="spec-field-row">
          <div class="spec-field-head">
            <label>${escapeHtml(field.label)}</label>
            ${lockBtn}
          </div>
          <select class="spec-input" data-field-key="${escapeHtml(field.key)}" data-field-type="select">${opts}</select>
        </div>
      `;
    }

    if (field.type === 'color') {
      return `
        <div class="spec-field-row spec-field-inline">
          <label>${escapeHtml(field.label)}</label>
          <div class="spec-inline-right">
            <input type="color" class="spec-color-input" data-field-key="${escapeHtml(field.key)}" data-field-type="color" value="${escapeHtml(val || '#ffffff')}" />
            ${lockBtn}
          </div>
        </div>
      `;
    }

    if (field.type === 'text') {
      return `
        <div class="spec-field-row">
          <div class="spec-field-head">
            <label>${escapeHtml(field.label)}</label>
            ${lockBtn}
          </div>
          <input type="text" class="spec-input" data-field-key="${escapeHtml(field.key)}" data-field-type="text" value="${escapeHtml(val || '')}" />
        </div>
      `;
    }

    // range + numeric readout
    const numVal = Number(val ?? field.min ?? 0);
    const unit = field.unit ? ` ${field.unit}` : '';
    return `
      <div class="spec-field-row">
        <div class="spec-field-head">
          <label>${escapeHtml(field.label)}</label>
          <div class="spec-head-right">
            <span class="spec-val-readout" data-readout-key="${escapeHtml(field.key)}">${escapeHtml(numVal)}${escapeHtml(unit)}</span>
            ${lockBtn}
          </div>
        </div>
        <div class="spec-range-pair">
          <input type="range" class="spec-range" data-field-key="${escapeHtml(field.key)}" data-field-type="range" data-unit="${escapeHtml(unit)}" min="${field.min}" max="${field.max}" step="${field.step || 1}" value="${numVal}" />
          <input type="number" class="spec-num-box" data-num-key="${escapeHtml(field.key)}" min="${field.min}" max="${field.max}" step="${field.step || 1}" value="${numVal}" />
        </div>
      </div>
    `;
  }

  function renderObjectsTabExtras(blueprint) {
    const fam = getSpecialtyFamily(state.familyId);
    const availGroups = Array.from(new Set([
      ...(fam?.defaultObjectGroups || []),
      ...Object.keys(OBJECT_GROUP_LABELS)
    ]));
    const disabledSet = new Set(state.disabledObjectGroups || []);

    const groupsHtml = availGroups.map((gk) => {
      const checked = !disabledSet.has(gk);
      const label = OBJECT_GROUP_LABELS[gk] || titleTagLabel(gk);
      return `
        <label class="spec-check-label spec-obj-group-row">
          <input type="checkbox" class="spec-obj-group-chk" data-group-key="${escapeHtml(gk)}" ${checked ? 'checked' : ''} />
          <span>${escapeHtml(label)}</span>
        </label>
      `;
    }).join('');

    const placed = blueprint?.objectDependencies || [];
    const missing = blueprint?.missingObjectDependencies || [];

    const missingHtml = missing.length > 0
      ? `<div class="spec-warning-box">Missing Object Dependencies: ${escapeHtml(missing.map((m) => `${m.familyId} (${m.reason})`).join(', '))}</div>`
      : '';

    const placedListHtml = placed.length > 0
      ? `<div class="spec-deps-list">${placed.slice(0, 14).map((p) => `<div class="spec-dep-chip">${escapeHtml(p.familyId)} / ${escapeHtml(p.presetId || 'default')}</div>`).join('')}${placed.length > 14 ? `<div class="spec-dep-chip">+${placed.length - 14} more</div>` : ''}</div>`
      : '<div class="spec-empty-note">No outdoor objects active for current settings.</div>';

    return `
      <div class="spec-section-subtitle">Object Category Filters</div>
      <div class="spec-obj-groups">${groupsHtml}</div>
      ${missingHtml}
      <div class="spec-section-subtitle">Active City Object Suite Placements (${placed.length})</div>
      ${placedListHtml}
    `;
  }

  function renderExportTabExtras() {
    return `
      <div class="spec-section-subtitle">Coordinate & Unit Format</div>
      <div class="spec-field-row">
        <label>Export Coordinate Axis</label>
        <select class="spec-input" id="spec-export-axis-select">
          <option value="y_up" ${state.exportAxis !== 'z_up' ? 'selected' : ''}>Standard glTF (Y-Up)</option>
          <option value="z_up" ${state.exportAxis === 'z_up' ? 'selected' : ''}>B Remastered (Z-Up)</option>
        </select>
      </div>
      <div class="spec-field-row">
        <label>Export Scale Units</label>
        <select class="spec-input" id="spec-export-units-select">
          <option value="meters" ${state.exportUnits !== 'b_units' ? 'selected' : ''}>Meters (1.0x)</option>
          <option value="b_units" ${state.exportUnits === 'b_units' ? 'selected' : ''}>B Game Units (16.404x)</option>
        </select>
      </div>
      <div class="spec-export-actions">
        <button type="button" class="spec-btn spec-btn-primary" id="spec-btn-export-glb"><i class="fas fa-cube"></i> Download Binary .Glb Model</button>
        <button type="button" class="spec-btn" id="spec-btn-export-bp"><i class="fas fa-drafting-compass"></i> Export Blueprint (.Specialty.Json)</button>
        <button type="button" class="spec-btn" id="spec-btn-export-json"><i class="fas fa-sliders"></i> Export Preset Settings (.Json)</button>
        <label class="spec-btn spec-file-btn">
          <i class="fas fa-file-import"></i> Import Blueprint or Settings (.Json)
          <input type="file" id="spec-import-file-input" accept=".json" hidden />
        </label>
      </div>
    `;
  }

  function renderTabBody(latestBlueprint = null) {
    if (!tabContentEl) return;
    const schema = getSchemaForFamily(state.familyId);
    const fields = schema.filter((f) => f.tab === activeTab);

    let lastGroup = '';
    const fieldHtml = fields.map((f) => {
      let hdr = '';
      if (f.group && f.group !== lastGroup) {
        lastGroup = f.group;
        hdr = `<div class="spec-section-subtitle">${escapeHtml(f.group)}</div>`;
      }
      return hdr + buildFieldHtml(f);
    }).join('');

    let extraHtml = '';
    if (activeTab === 'objects') extraHtml = renderObjectsTabExtras(latestBlueprint || studioApi.getLatestBlueprint());
    if (activeTab === 'export') extraHtml = renderExportTabExtras();

    tabContentEl.innerHTML = (fieldHtml || '<div class="spec-empty-note">No additional controls in this tab.</div>') + extraHtml;

    // Bind input listeners
    $$('[data-field-key]', tabContentEl).forEach((el) => {
      const key = el.dataset.fieldKey;
      const type = el.dataset.fieldType;
      const handler = () => {
        let nextVal;
        if (type === 'boolean') nextVal = Boolean(el.checked);
        else if (type === 'range') nextVal = Number(el.value);
        else nextVal = el.value;

        if (type === 'range') {
          const readout = $(`[data-readout-key="${key}"]`, tabContentEl);
          if (readout) readout.textContent = `${nextVal}${el.dataset.unit || ''}`;
          const numBox = $(`[data-num-key="${key}"]`, tabContentEl);
          if (numBox) numBox.value = String(nextVal);
        }
        onStateChange(key, nextVal);
      };
      el.addEventListener(type === 'range' || type === 'color' || type === 'text' ? 'input' : 'change', handler);
    });

    $$('[data-num-key]', tabContentEl).forEach((numEl) => {
      numEl.addEventListener('change', () => {
        const key = numEl.dataset.numKey;
        const val = Number(numEl.value);
        const rangeEl = $(`[data-field-key="${key}"]`, tabContentEl);
        if (rangeEl) rangeEl.value = String(val);
        const readout = $(`[data-readout-key="${key}"]`, tabContentEl);
        if (readout) readout.textContent = `${val}${rangeEl?.dataset.unit || ''}`;
        onStateChange(key, val);
      });
    });

    $$('[data-lock-key]', tabContentEl).forEach((btn) => {
      btn.addEventListener('click', () => {
        const key = btn.dataset.lockKey;
        if (locks.has(key)) locks.delete(key);
        else locks.add(key);
        renderTabBody();
      });
    });

    // Objects group checkboxes
    $$('.spec-obj-group-chk', tabContentEl).forEach((chk) => {
      chk.addEventListener('change', () => {
        const gk = chk.dataset.groupKey;
        const nextDisabled = new Set(state.disabledObjectGroups || []);
        if (chk.checked) nextDisabled.delete(gk);
        else nextDisabled.add(gk);
        onStateChange('disabledObjectGroups', Array.from(nextDisabled));
      });
    });

    // Export actions
    const axisSel = $('#spec-export-axis-select', tabContentEl);
    if (axisSel) axisSel.addEventListener('change', () => onStateChange('exportAxis', axisSel.value));
    const unitSel = $('#spec-export-units-select', tabContentEl);
    if (unitSel) unitSel.addEventListener('change', () => onStateChange('exportUnits', unitSel.value));
    const btnGlb = $('#spec-btn-export-glb', tabContentEl);
    if (btnGlb) btnGlb.addEventListener('click', onExportGLB);
    const btnBp = $('#spec-btn-export-bp', tabContentEl);
    if (btnBp) btnBp.addEventListener('click', onExportBlueprint);
    const btnJson = $('#spec-btn-export-json', tabContentEl);
    if (btnJson) btnJson.addEventListener('click', onExportSettings);

    const fileInput = $('#spec-import-file-input', tabContentEl);
    if (fileInput) {
      fileInput.addEventListener('change', async () => {
        const file = fileInput.files?.[0];
        if (!file) return;
        try {
          const text = await file.text();
          const parsed = parseImportedSpecialtyJson(text);
          onImportParsed(parsed);
          toast(`Imported ${file.name}`);
        } catch (err) {
          toast(`Import Error: ${err.message}`);
        }
        fileInput.value = '';
      });
    }
  }

  function syncToolbarInputs() {
    if (seedInputEl) seedInputEl.value = String(state.seed || 2026);
    if (varStrengthEl) varStrengthEl.value = state.variationStrength || 'subtle';
    if (chkLayerA) chkLayerA.checked = state.includeBuildingLayer !== false;
    if (chkLayerB) chkLayerB.checked = state.includeLot !== false;
    if (chkLayerC) chkLayerC.checked = state.includeObjectsLayer !== false;
  }

  // Bind persistent catalog & toolbar controls
  if (categorySelectEl) {
    categorySelectEl.addEventListener('change', () => {
      activeCategory = categorySelectEl.value;
      renderCatalog();
    });
  }
  if (envSelectEl) {
    envSelectEl.addEventListener('change', () => {
      activeEnvTag = envSelectEl.value;
      renderCatalog();
    });
  }
  if (searchInputEl) {
    searchInputEl.addEventListener('input', () => {
      searchQuery = searchInputEl.value;
      renderCatalog();
    });
  }
  if (seedInputEl) {
    seedInputEl.addEventListener('change', () => {
      onStateChange('seed', Math.max(1, parseInt(seedInputEl.value, 10) || 2026));
    });
  }
  if (varStrengthEl) {
    varStrengthEl.addEventListener('change', () => {
      onStateChange('variationStrength', varStrengthEl.value);
    });
  }
  if (chkLayerA) chkLayerA.addEventListener('change', () => onStateChange('includeBuildingLayer', chkLayerA.checked));
  if (chkLayerB) chkLayerB.addEventListener('change', () => onStateChange('includeLot', chkLayerB.checked));
  if (chkLayerC) chkLayerC.addEventListener('change', () => onStateChange('includeObjectsLayer', chkLayerC.checked));

  const btnSeedRand = $('#spec-btn-rand-seed');
  if (btnSeedRand) btnSeedRand.addEventListener('click', onRandomizeSeed);
  const btnRandAll = $('#spec-btn-rand-all');
  if (btnRandAll) btnRandAll.addEventListener('click', onRandomizeAll);
  const btnReset = $('#spec-btn-reset-preset');
  if (btnReset) btnReset.addEventListener('click', onResetPreset);
  const btnSaveCfg = $('#spec-btn-save-config');
  if (btnSaveCfg) {
    btnSaveCfg.addEventListener('click', () => {
      const fam = getSpecialtyFamily(state.familyId);
      const savedName = $('#spec-save-name-input')?.value?.trim() || `${fam?.label || state.familyId} (${state.seed})`;
      saveSpecialtyConfig(savedName, state);
      if ($('#spec-save-name-input')) $('#spec-save-name-input').value = '';
      renderSavedConfigs();
      toast(`Saved "${savedName}"`);
    });
  }

  populateStaticFilters();
  renderCatalog();
  renderSavedConfigs();
  renderTabsBar();
  renderTabBody();
  syncToolbarInputs();

  return {
    refresh(blueprint) {
      renderCatalog();
      syncToolbarInputs();
      renderTabBody(blueprint);
    },
    setActiveTab(tabId) {
      activeTab = tabId;
      renderTabsBar();
      renderTabBody();
    }
  };
}

  // --- Module: index.js ---
function showToast(msg) {
  const el = $('#spec-toast');
  if (!el) return;
  el.textContent = msg;
  el.classList.add('is-visible');
  clearTimeout(showToast._timer);
  showToast._timer = setTimeout(() => el.classList.remove('is-visible'), 2600);
}

function updateStatsOverlay(buildingGroup) {
  const bp = buildingGroup?.userData?.blueprint;
  if (!bp) return;
  const setText = (sel, text) => {
    const el = $(sel);
    if (el) el.textContent = text;
  };
  const bSize = bp.bounds?.buildingMeters?.size || { x: 0, y: 0, z: 0 };
  const lSize = bp.bounds?.lotMeters?.size || { x: 0, y: 0, z: 0 };
  const lotInfo = bp.layers?.layerB_PropertyLot;
  const gStats = bp.geometryStats || { totalMeshes: 0, totalTriangles: 0 };
  const deps = bp.objectDependencies || [];
  setText('#stat-dims', `${bSize.x}m x ${bSize.z}m x ${bSize.y}m`);
  setText('#stat-lot', lotInfo?.enabled ? `${lSize.x}m x ${lSize.z}m (${lotInfo.parkingStalls?.length || 0} Stalls)` : 'No Lot (Building Only)');
  setText('#stat-stats', `${gStats.totalMeshes} Meshes | ${gStats.totalTriangles} Tris`);
  setText('#stat-objects', `${deps.length} Props Placed | ${bp.entrances.length} Entrances`);
  setText('#spec-blueprint-preview', JSON.stringify({
    schemaVersion: bp.schemaVersion,
    familyId: bp.familyId,
    presetId: bp.presetId,
    seed: bp.seed,
    bounds: bp.bounds,
    entrances: bp.entrances,
    placementAnchorsCount: bp.placementAnchors.length,
    objectDependencies: deps,
    missingObjectDependencies: bp.missingObjectDependencies
  }, null, 2));
}

function specLoadScript(url) {
  return new Promise((resolve, reject) => {
    const existing = Array.from(document.querySelectorAll('script')).find((s) => s.src === url);
    if (existing && (typeof THREE !== 'undefined')) {
      resolve();
      return;
    }
    const script = document.createElement('script');
    script.src = url;
    script.async = true;
    script.onload = () => resolve();
    script.onerror = () => reject(new Error(`Failed to load ${url}`));
    document.head.appendChild(script);
  });
}

async function specEnsureThree() {
  if (typeof THREE === 'undefined') {
    await specLoadScript('https://cdn.jsdelivr.net/npm/three@0.128.0/build/three.min.js');
  }
  if (!THREE.OrbitControls) {
    await specLoadScript('https://cdn.jsdelivr.net/npm/three@0.128.0/examples/js/controls/OrbitControls.js');
  }
  if (!THREE.GLTFExporter) {
    await specLoadScript('https://cdn.jsdelivr.net/npm/three@0.128.0/examples/js/exporters/GLTFExporter.js');
  }
}

async function initSpecialtyBuildingStudio() {
  ensureSpecialtyBuildingRegistry();
  const canvasEl = $('#specialty-canvas');
  if (!canvasEl) return;

  try {
    await specEnsureThree();
  } catch (err) {
    console.error('Three.js load failed:', err);
    showToast('Failed To Load 3d Renderer');
    return;
  }
  if (typeof THREE === 'undefined') return;

  const state = copy(buildDefaultSpecialtyConfig('gas_station', 'modern_corporate_gas_station'));
  const locks = new Set();
  const preview = createSpecialtyPreview(canvasEl);

  let currentBuilding = null;
  let controlsUi = null;
  let rebuildScheduled = false;

  function rebuild(autoFrame = false) {
    currentBuilding = createSpecialtyBuilding(state, { locks });
    preview.setModel(currentBuilding, state);
    if (autoFrame) {
      preview.frameCamera('full');
    }
    updateStatsOverlay(currentBuilding);
    if (controlsUi) {
      controlsUi.refresh(currentBuilding.userData?.blueprint);
    }
  }

  function scheduleRebuild(autoFrame = false) {
    if (rebuildScheduled) return;
    rebuildScheduled = true;
    requestAnimationFrame(() => {
      rebuildScheduled = false;
      rebuild(autoFrame);
    });
  }

  controlsUi = createSpecialtyControls({
    state,
    locks,
    toast: showToast,
    getLatestBlueprint: () => currentBuilding?.userData?.blueprint || null,
    onStateChange(key, value) {
      state[key] = value;
      scheduleRebuild(key === 'lotType' || key === 'includeLot');
    },
    onSelectFamily(familyId) {
      const fam = getSpecialtyFamily(familyId);
      if (!fam || !fam.presets.length) return;
      const firstPreset = fam.presets[0];
      const next = applySpecialtyPresetWithLocks(state, firstPreset.id, locks);
      Object.assign(state, next);
      rebuild(true);
      showToast(`Selected ${fam.label}`);
    },
    onSelectPreset(presetId) {
      const preset = getSpecialtyPreset(presetId);
      if (!preset) return;
      const next = applySpecialtyPresetWithLocks(state, presetId, locks);
      Object.assign(state, next);
      rebuild(true);
      showToast(`Preset: ${preset.label}`);
    },
    onRandomizeSeed() {
      state.seed = Math.floor(Math.random() * 900000) + 1000;
      rebuild(false);
      showToast(`New Seed: ${state.seed}`);
    },
    onRandomizeAll() {
      const next = randomizeSettings(state, state.seed + 37, locks);
      Object.assign(state, next);
      rebuild(false);
      showToast(`Randomized Variation (${state.seed})`);
    },
    onResetPreset() {
      const next = buildDefaultSpecialtyConfig(state.familyId, state.presetId);
      Object.assign(state, next);
      rebuild(true);
      showToast('Reset To Clean Preset Defaults');
    },
    onExportGLB() {
      exportSpecialtyGLB(currentBuilding, state, showToast);
    },
    onExportBlueprint() {
      exportSpecialtyBlueprint(currentBuilding, state, showToast);
    },
    onExportSettings() {
      exportSpecialtySettings(state, showToast);
    },
    onImportParsed(parsed) {
      Object.assign(state, sanitiseSpecialtyConfig(parsed.settings));
      rebuild(true);
    }
  });

  // Preview Toolbar & Top Quick Actions
  const bindClick = (sel, fn) => {
    const el = $(sel);
    if (el) el.addEventListener('click', fn);
  };
  bindClick('#spec-top-rand', () => {
    const next = randomizeSettings(state, state.seed + 37, locks);
    Object.assign(state, next);
    rebuild(false);
    showToast(`Randomized Variation (${state.seed})`);
  });
  bindClick('#spec-top-seed', () => {
    state.seed = Math.floor(Math.random() * 900000) + 1000;
    rebuild(false);
    showToast(`New Seed: ${state.seed}`);
  });
  bindClick('#spec-top-bp', () => exportSpecialtyBlueprint(currentBuilding, state, showToast));
  bindClick('#spec-top-glb', () => exportSpecialtyGLB(currentBuilding, state, showToast));
  bindClick('#spec-fullscreen', () => {
    const el = $('.specialty-project-card') || document.documentElement;
    if (!document.fullscreenElement) {
      el.requestFullscreen?.().catch(() => {});
    } else {
      document.exitFullscreen?.().catch(() => {});
    }
  });
  bindClick('#spec-cam-full', () => preview.frameCamera('full'));
  bindClick('#spec-cam-street', () => preview.frameCamera('street'));
  bindClick('#spec-cam-building', () => preview.frameCamera('building'));
  bindClick('#spec-cam-roof', () => preview.frameCamera('roof'));
  bindClick('#spec-btn-snapshot', () => preview.captureSnapshot(state));

  const chkTurn = $('#spec-toggle-turntable');
  if (chkTurn) chkTurn.addEventListener('change', () => preview.setTurntable(chkTurn.checked));
  const chkGrid = $('#spec-toggle-grid');
  if (chkGrid) chkGrid.addEventListener('change', () => preview.setGridVisible(chkGrid.checked));
  const chkHuman = $('#spec-toggle-human');
  if (chkHuman) chkHuman.addEventListener('change', () => preview.setScaleHumanVisible(chkHuman.checked));
  const chkGizmos = $('#spec-toggle-gizmos');
  if (chkGizmos) chkGizmos.addEventListener('change', () => preview.setGizmosVisible(chkGizmos.checked));
  const chkWire = $('#spec-toggle-wire');
  if (chkWire) chkWire.addEventListener('change', () => preview.setWireframe(chkWire.checked));
  const chkSil = $('#spec-toggle-sil');
  if (chkSil) chkSil.addEventListener('change', () => preview.setSilhouette(chkSil.checked));

  const btnTheatre = $('#spec-btn-theatre');
  if (btnTheatre) {
    btnTheatre.addEventListener('click', () => {
      document.body.classList.toggle('studio-theatre-mode');
      setTimeout(() => preview.resize(), 60);
    });
  }

  document.addEventListener('keydown', (e) => {
    if (e.target && ['INPUT', 'TEXTAREA', 'SELECT'].includes(e.target.tagName)) return;
    const k = e.key.toLowerCase();
    if (k === 's') {
      state.seed = Math.floor(Math.random() * 900000) + 1000;
      rebuild(false);
    } else if (k === 'f') {
      preview.frameCamera('full');
    } else if (k === 't' && chkTurn) {
      chkTurn.checked = !chkTurn.checked;
      preview.setTurntable(chkTurn.checked);
    } else if (k === 'h' && chkHuman) {
      chkHuman.checked = !chkHuman.checked;
      preview.setScaleHumanVisible(chkHuman.checked);
    } else if (k === 'p') {
      preview.captureSnapshot(state);
    } else if (k === 'e') {
      exportSpecialtyGLB(currentBuilding, state, showToast);
    } else if (k === 'escape' && document.body.classList.contains('studio-theatre-mode')) {
      document.body.classList.remove('studio-theatre-mode');
      setTimeout(() => preview.resize(), 60);
    }
  });

  rebuild(true);
}

// Expose global headless & cross-tool API
ensureSpecialtyBuildingRegistry();

const BSpecialtyBuildingSuite = {
  BUILDING_CATEGORIES,
  ARCHITECTURAL_ERAS,
  CONDITION_LEVELS,
  LOT_TYPES,
  BASE_BUILDING_CONFIG,
  SHARED_CONTROL_TABS,
  ensureSpecialtyBuildingRegistry,
  getAllSpecialtyFamilies,
  getAllSpecialtyPresets,
  getSpecialtyFamily,
  getSpecialtyPreset,
  searchSpecialtyCatalog,
  buildDefaultSpecialtyConfig,
  sanitiseSpecialtyConfig,
  applySpecialtyPresetWithLocks,
  createPlacementContext,
  registerBuildingFootprint,
  registerEntranceClearance,
  validateAndReservePlacement,
  createSpecialtyBuilding,
  validateSpecialtyBlueprint,
  buildScopedExportRoot,
  exportSpecialtyGLB
};

if (typeof window !== 'undefined') {
  window.BSpecialtyBuildingSuite = BSpecialtyBuildingSuite;
}

if (typeof document !== 'undefined') {
  if (document.readyState === 'loading' && typeof document.addEventListener === 'function') {
    document.addEventListener('DOMContentLoaded', initSpecialtyBuildingStudio);
  } else if ($('#specialty-canvas')) {
    initSpecialtyBuildingStudio();
  }
}

